export const ordenacoesLivro1TitulosLxxiALxxx: HistoricalDocument = {
  id: 'ordenacoes-livro-1-titulos-lxxi-a-lxxx',
  title: 'Ordenações Filipinas — Títulos LXXI a LXXX',
  subtitle: 'Do Scrivão da Camera',
  date: '1603',
  era: 'Idade Moderna',
  language: 'Português',
  description: `Títulos LXXI a LXXX do Livro Primeiro das Ordenações Filipinas: de "Do Scrivão da Camera" a "Das causas, que são comuns aos Tabelliães das Notas e aos do Judicial".`,
  parentCollectionId: 'ordenacoes-livro-1',
  sections: [
    {
      id: 'titulo-lxxi',
      title: `LXXI. Do Scrivão da Camera`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxi-preambulo', number: 'Preâmbulo', text: `O Scrivão da Camera fará em cada hum anno livro da receita de todo o que as rendas do Concelho renderem, pondo cada huma renda sobre si, e a quem he arrendada, e por quanto preço, e os tempos, em que se hão de fazer as pagas, e quaes são os fiadores; e em outra parte deste livro porá todas as despesas, que fizer o Thesoureiro, ou quem o tal cargo servir. As quaes despesas assentará pelo miudo, bem declaradas, em maneira, que sempre se possa tomar a conta dellas.` },
        { id: 'of1-tlxxi-1', number: '1', text: `E não se farão despesas algumas, senão com acordo dos Véreadores e Officiaes do Concelho; o qual acordo serverá o Scrivão no livro em titulo apartado, e será assinado pelos Véreadores e Officiaes, que no dito acordo forem. E em outra maneira não screverá o Scrivão despesa alguma no dito livro.

Estas reclamações acabárão por ser desprezadas totalmente, expedindo o Rey as provisões para taes Ofícios.

Mas a demissão do funcionário depende muitas vezes do placet do Governo, que póde ex ri do art. 73 fazer reintegrar o demitido. Tal a latitude que se tem dado ao citado art.

As obrigamentes e vencimentos do Secretário admittidos foram regulamentarios na Lei antepenultima citada.` },
        { id: 'of1-tlxxi-2', number: '2', text: `Outrosi todas as despesas miudas, que se fizerem, se farão perante o Scrivão da Camera; o qual fará canhenho apartado, em que ponha as ditas despesas miudas, e o levará à Véreação, e o mostrará aos Véreadores. E as despesas, que os Véreadores houverem por boas e bem feitas, assentará no livro da Camera, e per quem, e por cujo mandado foram feitas, e os ditos Véreadores as assinarão.` },
        { id: 'of1-tlxxi-3', number: '3', text: `E todos os mandados e acordos, per que se hajam de fazer algumas cousas, screverá em hum livro para isso ordenado; os quaes acordos serão assinados per aquelles, que os acordarem e mandarem.` },
        { id: 'of1-tlxxi-4', number: '4', text: `Ao Scrivão da Camera pertence screver nos feitos das injurias verbaes, que em Camera forem despachados, se depois que os feitos forem conclusos em final, for necessário per mandado dos Juizes e Véreadores screver alguma cousa nelles. Porém, emquanto se o feito processar perante o Juiz, aos Tabelliães dante elle pertence screver no dito feito; e depois que a sentença for dada e publicada na Camera, torne o feito ao Tabellião, que o processou. E se o Scrivão da Camera não tiver scripto nelle mais, que a publicação, levará quatorze réis della, sem ir o feito ao Contador.` },
        { id: 'of1-tlxxi-5', number: '5', text: `E outrosi a elle pertence screver todas as Cartas testemunhaveis de quaesquer requerimentos, que se fizerem aos Véreadores e Officiaes da Camera, que houverem de passar sob sinal dos ditos Véreadores, e serão selladas com o sello do Concelho. Outrosi screverá nas eleições dos Véreadores e Officiaes da Camera, que se fizerem pelos Corregedores per bem de nossas Ordenações, ou per nosso mandado.` },
        { id: 'of1-tlxxi-6', number: '6', text: `Item, terá huma das chaves da arca do Concelho, em que hão de star as scripturas delle, como dissemos no Titulo 66: Dos Véreadores, § 15: Item farão.` },
        { id: 'of1-tlxxi-7', number: '7', text: `E em principio de cada mez na primeira Véreação, que se fizer, lerá e publicará aos Officiaes da Véreação e aos Almotacés seus Regimentos. E todas as ditas publicações serão assinadas pelos ditos Officiaes, sob pena de pagar duzentos réis para as despesas da Camera, cada vez que o assi não fizer; os quaes o Procurador do Concelho fará screver sobre o dito Scrivão da Camera, ao Scrivão da Almotaceria.

M — liv. 1 t. 52 § 8.` },
        { id: 'of1-tlxxi-8', number: '8', text: `Terá hum livro, em que screverá em titulo apartado os assentos dos gados (pela maneira, que se dirá no Livro quinto, Titulo 415: Da passagem dos gados, paragrapho 9: Mandamos), contas e descargas delles, fazendo em cada pagina hum assento. E do gado, que screverá, ora seja muito, ora pouco, levará sómente oito réis.` },
        { id: 'of1-tlxxi-9', number: '9', text: `E de todos os assentos, que fizer em seus livros per mandado dos Officiaes, a requerimento de partes, assi como obrigações, fianças e outros semelhantes, levará de cada hum seis réis.` },
        { id: 'of1-tlxxi-10', number: '10', text: `E levará oito réis de cada Alvará, que fizer, que houver de ser assinado pelos Officiaes da Camera, ou per cada hum delles. Porém, se em alguns lugares stão em costume de levar menos, do que aqui he conteúdo, ou de não levar cousa alguma, não a levarão. E no mais, que não for provído expressamente per este Regimento do que hão de levar, levarão ás regras, como os Scrivães do Judicial.` },
      ],
    },
    {
      id: 'titulo-lxxii',
      title: `LXXII. Do Scrivão da Almotaceria`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxii-preambulo', number: 'Preâmbulo', text: `O Scrivão da Almotaceria screverá todas as achadas, assi de gados e bestas, como os assentos de Carniceiros, Pádeiras, Regateiras e outras quaesquer pessoas, que em coimas caírem, que pelos Rendeiros e Jurados lhe for notificado. E assi screverá todas as outras pessoas, que elle souber, Como as causas pertencentes áquelle Juizo passárão para o de Paz, os Escrivães respectivos substituírão os dos Almotacés; e posteriormente como essas causas se dividirão conforme as alçadas, ficárão á cargo dos Escrivães de cada Juizo os respectivos processos.

que vão contra as posturas do Concelho. E cada mez mostrará as ditas achadas aos Almotacés. E se os Almotacés não procederem contra os culpados, mostre-as aos Juizes e Véreadores, para saberem quaes são os daninhos, e se executarem nelles as Ordenações e posturas do Concelho, feitas sobre os daninhos. E não o fazendo assi o dito Scrivão, pagará em dobro para o Concelho todas as coimas e penas, que assi não mostrará aos Almotacés, ou aos Juizes e Véreadores.` },
        { id: 'of1-tlxxii-1', number: '1', text: `E trabalhará de saber, se os Rendeiros, ou Jurados, tem feito avenças com aquelles, que podem caír em coimas, antes de as terem feitas, ou lhes serem julgadas. E se achar que taes avenças fazem, antes de as coimas lhes serem julgadas per sentença, o notifique aos Juizes para os punirem, segundo fórma de nossas Ordenações. E isto cumprirá assi, sob pena de ser suspenso do Officio pelo tempo, que ao Julgador parecer.` },
        { id: 'of1-tlxxii-2', number: '2', text: `Item, screverá todas as penas, em que incorrerem os Almotacés por não cumprirem as cousas, que em seu Regimento lhes são mandadas, sob pena de pagar em dobro para o Concelho as penas, que assi não screver. E emfim de cada mez levará á Camera estas penas, em que assi os Almotacés tiverem incorrido, e as mostrará aos Juizes, para as mandarem executar nos Almotacés, que nellas incorreram.` },
        { id: 'of1-tlxxii-3', number: '3', text: `E no lugar em que assi tiver o dito Officio, e em seu termo, não poderá trazer, nem criar gado algum, mais que o que lhe for necessário para sua lavoura; o qual lhe será ordenado pelo Corregedor da Comarca, informando-se de pessoas, que razão tenham de o saber. E do que assi lhe ordenar, se fará assento no livro da Camera, assinado pelo dito Corregedor. E se em outra maneira trouxer gado, perdel-o-ha, ametade para quem o accusar, e outra para os Captivos, e perderá o Officio.

Salario.` },
        { id: 'of1-tlxxii-4', number: '4', text: `E levará de seu salario de huma aucão e contestação, e mandado para se perguntarem testemunhas seis réis; e não havendo mandado para se perguntarem testemunhas, levará sómente quatro réis.` },
        { id: 'of1-tlxxii-5', number: '5', text: `Item, de huma absolvição de instancia do Juízo, assentada no caderno, quatro réis.` },
        { id: 'of1-tlxxii-6', number: '6', text: `Item, de huma appellação entre partes para o Juiz, ou Camera, seis réis.` },
        { id: 'of1-tlxxii-7', number: '7', text: `Item, de huma testemunha seis réis.` },
        { id: 'of1-tlxxii-8', number: '8', text: `Item, de huma sentença oito réis.` },
        { id: 'of1-tlxxii-9', number: '9', text: `Item, de huma pena posta entre partes oito réis.` },
        { id: 'of1-tlxxii-10', number: '10', text: `Item, do provimento pela villa, ou cidade aos Marceiros, Boticarios, Mercadores de panno de lãa e de linho, e Regateiras, quatro réis de cada casa, quando os acharem em culpa. E dos que não acharem em culpa, não levará cousa alguma.` },
        { id: 'of1-tlxxii-11', number: '11', text: `E se houver causas, em que se houver de ordenar feito algum, e guardar a ordem do Juizo, levarão o que he ordenado aos outros Scrivães, segundo se contém no Título 84: Do que hão de levar os Tabellães e Scrivães de seus Offícios.` },
      ],
    },
    {
      id: 'titulo-lxxiii',
      title: `LXXIII. Dos Quadrilheiros`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxiii-preambulo', number: 'Preâmbulo', text: `Em todas as cidades, villas, lugares e seus termos, haverá Quadrilheiros, para que melhor se prendam os malfeitores. Para o que se ajuntarão em Camera os Juizes e Véreadores, e terão em hum rol todos os moradores do lugar e seu termo, e a cada vinte moradores, que hajam de servir em quadrilha, que mais visinhos tiverem, ordenarão hum Quadrilheiro, que para isso mais pertencente lhes parecer. E feitos assi os Quadrilheiros, ficarão scriptos no livro da Camera pelo Serivão della, para servirem tres annos com as quadrilhas, que lhes forem ordenadas. E ser-lhes-ha dado juramento em Camera, que bem e verdadeiramente cumpram este Regimento. E acabados os tres annos, ordenarão outros. E se durando os ditos tres annos fallecer algum, ou se absentar de absencia prolongada, os Juizes e Véreadores farão outro em seu lugar, que acabe de servir os tres annos, ou até o outro vir, quando for feito por sua absencia prolongada.` },
        { id: 'of1-tlxxiii-1', number: '1', text: `E cada Quadrilheiro terá vinte homens de sua quadrilha, os quaes lhe serão dados em rol ao tempo, que receber juramento. E o traslado do dito rol ficará na Camera, para se saber os que lhe forão ordenados; e serão obrigados todas as ditas vinte pessoas a terem continuadamente lança de dezoito palmos para cima, ou ao menos meia lança. E as mesmas armas terão os moradores dos termos e terras chãs, para tanto que huns e outros ouvirem algum appellido, ou chamar o Quadrilheiro, poderem logo ir onde lhes for mandado, ou cumprir por nosso serviço e bem de justiça. E o que não tiver em casa as ditas armas, pague por cada vez cincoenta réis para o Meirinho, que o accusar.` },
        { id: 'of1-tlxxiii-2', number: '2', text: `E será cada Quadrilheiro muito diligente em saber para sua informação (sem sobre isso tirar inquirição), se em sua quadrilha se fazem furtos, ou outros crimes: e quaes são as pessoas, que nisso tem culpa, para quando por hi vier o Corregedor, lho fazer saber. E assi o fará saber aos Juizes, para fazerem tudo o que per bem de nossas Ordenações podem e devem fazer.

Esta palavra, que hoje se toma em máo sentido, em outro tempo, diz Moraes, designava uma pessoa grave, de confiança e mui privilegiada, como a latina Irenarcha.

Ao Rey D. Fernando I se deve a creação desses Offíciaes, que distribui aos pares por cada Parochia de Lisboa. Traziâo por insignia uma vara pintada de verde com as armas Reaes.` },
        { id: 'of1-tlxxiii-3', number: '3', text: `Outrosi serão muito diligentes em saberem se em suas quadrilhas andam homens vadios, ou de má fama, ou estrangeiros, e logo lhes tomem conta do que ahi fazem. E não lhes dando elles alguma justa e verdadeira razão, por que tenham causa de ahi andarem, os prendam e levem ao Juiz, antes de serem mettidos na cadea. O qual lhes tomará conta de quem são, e do que hi fazem. E achando-os em culpa, os prendam, e faça delles justiça com appellação e aggravo. E dando o tal homem razão, por que pareça claramente, que tem necessidade de star na terra, o Juiz lhe mande, que em certo tempo, que lhe parecer que bastará, acabe o que ahi tiver para fazer, sob pena de ser preso. E sendo depois achado, passado o termo, que lhe o Juiz der, os Quadrilheiros o prendam, e levem ao Juiz, como dito he. E qualquer Quadrilheiro, que em sua quadrilha consentir andarem as semelhantes pessoas, sem cumprirem o que lhes aqui he mandado, incorrerá em pena de trezentos réis para o Meirinho, ou Alcaide. E além disso, se a tal pessoa vadia, ou estrangeira fizer algum furto, ou dano, o Quadrilheiro com os da sua quadrilha, que consentirem entre si andar a tal pessoa, pagarão à parte danificada o dano, que receber.` },
        { id: 'of1-tlxxiii-4', number: '4', text: `E saberão se em suas quadrilhas ha casas de alcouce, ou de tabolagem, ou em que se recolham furtos, barregueiros casados, alcoviteiras, feiticeiras, para o que visitarão as stalagens e vendas de suas quadrilhas; ou mulheres, que stêm infamadas de fazerem mover outras, ou se andando alguma prenhe, se suspeite mal do parto, não dando delle conta. E havendo alguma das ditas cousas, o farão saber ás Justiças, a que pertencer: e na cidade de Lisboa ao Corregedor e Juiz do seu bairro; os quaes se informarão, e achando prova bastante para prender os culpados, os prenderão, e procederão, como for justiça.` },
        { id: 'of1-tlxxiii-5', number: '5', text: `E os Juizes, tanto que os Tabelliães lhes derem os roes dos culpados, darão perante hum Tabellião a cada Quadrilheiro hum rol dos que devem ser presos. E os ditos Quadrilheiros farão de maneira, que se cada hum dos culpados, que lhes os Juizes derem em rol, andar em sua quadrilha, o prendam, lançando logo, onde quer que o virem, appellido, dizendo: Prendei foão da parte del Rei nosso Senhor: à qual voz sairão logo todos os de sua quadrilha, e de quadrilha em quadrilha o sigam, até ser preso, sob pena daquelle Quadrilheiro, ou quadrilha, por cuja culpa, ou falta o tal homiziado deixar de ser preso, pagar à parte danificada o que lhe pagara o dito homiziado, se fora preso. E além disso o Quadrilheiro, que em sua quadrilha deixar andar alguma pessoa das que lhe forem dadas em rol, incorrerá em pena de quinhentos réis para o Meirinho, ou Alcaide, que o accusar.` },
        { id: 'of1-tlxxiii-6', number: '6', text: `E serão os Quadrilheiros e homens de suas quadrilhas diligentes em acudir ás voltas e arroidos com suas armas, e farão de maneira, que prendam os culpados. E se logo nos arroidos os não poderem prender, corram depois elles com appellido de huma quadrilha em outra, até serem presos. E deixando os culpados de ser presos por sua falta, serão obrigados pagar à parte danificada o dano, que receberam, e poderam haver do malfeitor, se fora preso. E além disto o Quadrilheiro, que não acudir aos arroidos, pagará cem réis, e cada pessoa de sua quadrilha cincoenta réis para o Meirinho, ou Alcaide, que os accusar.` },
        { id: 'of1-tlxxiii-7', number: '7', text: `E sendo caso, que seguindo algum Quadrilheiro algum homiziado para o prender, elle se acolher para casa de algum poderoso, Duque, Marquez, Conde, Arcebispo, Bispo, Prelado, Senhor de terras, ou Fidalgo principal, poderá entrar, e entre livremente na tal casa a buscar e prender o dito homiziado, sem da parte das ditas pessoas, parentes, ou criados lhe ser posto impedimento, nem duvida alguma na entrada da casa, busca e prisão do dito homiziado. E pela dita maneira entrarão em quaesquer lugares e terras, inda que sejam de Senhorios, ou Contos, ou de outra jurisdição, sem embargo de quaesquer doações, privilegios e posses, que em contrario haja, até o delinquente com effeito ser preso. E qualquer das ditas pessoas, que o contrario fizer, incorrerá nas penas, que diremos no Livro quinto, Titulo 104: Que os Prelados e Fidalgos não acoutem malfeitores. E tendo o Quadrilheiro Tabellião, faça de tudo auto. E não o tendo, tome de tudo testemunhas, e antes que vá a sua casa, se vá ao Juiz da terra, o qual fará auto, e procederá per elle, para lhe ser entregue o malfeitor, ou envie o auto ao Corregedor da Comarca, para proceder. E nos taes casos as Justiças farão de tudo autos publicos, que nos enviarão, emprazando as ditas pessoas grandes, que forem culpadas, que em certo termo pareçam pessoalmente em nossa Corte.` },
        { id: 'of1-tlxxiii-8', number: '8', text: `E o que dissemos dos homizados, que podem e devem ser presos nas casas dos Arcebispos, Bispos, Dom-Abbades e Priores de Mosteiros, se entenderá, não sendo as casas taes, que per Direito, ou costume devam gozar da immunidade da Igreja nos casos, em que ella val.` },
        { id: 'of1-tlxxiii-9', number: '9', text: `E queremos, que tanto que os Juizes, ou Quadrilheiros souberem, que algum malfeitor se acolhe em casa dos ditos Priores e Dom-Abbades, lhes digam e requeiram, que os lancem fóra, notificando-lhes como são homizados. E tendo-os elles mais, ou trazendo-os comsigo, façam disso auto, e o enviem ao Corregedor, o qual procederá contra elles a suspensão da jurisdição, que tiverem.` },
        { id: 'of1-tlxxiii-10', number: '10', text: `E quando o tal homizado tiver commettido crime, porque lhe não valha o Couto do dito Mosteiro (pela obrigação, em que os Dom-Abbades e Priores são, de os não acolherem, nem ampararem), não se lhes fará requerimento, que os lancem fóra, mas prendel-os-hão em suas casas, se o poderem fazer, sem se seguir cousa contra nosso serviço. E em outra maneira, façam auto, e o enviem ao dito Corregedor.` },
        { id: 'of1-tlxxiii-11', number: '11', text: `E os Corregedores pelos lugares, onde andarem, ou stiverem, saberão com diligencia se os Quadrilheiros cumprem este Regimento. E procedam contra os que acharem em culpa.

Privilegios.` },
        { id: 'of1-tlxxiii-12', number: '12', text: `E em quanto os Quadrilheiros da cidade de Lisboa usarem o dito Officio, haverão para si as armas; que tomarem aos ladrões, que prendem; e as que tomarem nas brigas, que confórme as Ordenações se perderem. E poderão protestar por as penas dos arrancamentos, e demandal-as ás pessoas, que prenderem, e lhes serão julgadas, como aos Alcaides. E os visinhos, que stiverem ordenados ás suas quadrilhas, que lhes não acudirem, chamando elles por ella, pagará cada hum quinhentos réis, ametade para o Quadrilheiro, dando disso duas testemunhas, e a outra para Captivos.` },
        { id: 'of1-tlxxiii-13', number: '13', text: `E sendo os Quadrilheiros da dita cidade achados de noite com suas varas, a quaesquer horas, nos bairros, que lhes são ordenados, ora venham de fazer alguma diligencia, ora não, não lhes levem penas, nem percam as armas, salvo sendo achados commettendo algum delicto.` },
        { id: 'of1-tlxxiii-14', number: '14', text: `E bem assi, apenando-se alguma gente para ir em armadas, elles não serão a isso constrangidos.` },
        { id: 'of1-tlxxiii-15', number: '15', text: `E as resistencias, que lhes forem feitas, sejam castigadas, como se fossem feitas aos Alcaides.` },
      ],
    },
    {
      id: 'titulo-lxxiv',
      title: `LXXIV. Dos Alcaides Móres`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxiv-preambulo', number: 'Preâmbulo', text: `Como a guarda de hum Castello del Rei, ou de outro Senhor he cousa tão importante e perigosa, que o que o perde por sua culpa, ou negligencia, cáe em crime de traição, que he o mais grave e feio caso, que hum homem póde commeter: o que Castello aceitar deve ter as partes, que para cousa de tanta importancia e conliança se requere. Primeiramente, deve ser de boa linhagem da parte de seu pai e mãi, porque assi se sperará, que não faça cousa, por que elle, e os que delle descenderem, se possam affrontar. Item, deve ser esforçado para resistir ás forças dos contrários e soffrer os trabalhos de fome, sede, frio e todos os mais, que, sendo cercado, lhe podem acontecer, e não desamparar o Castello no tempo do perigo, nem o entregar por ameaças, ou medo algum de prisão, feridas, tormentos, ou morte de sua pessoa, ou de mulher, ou filhos, ou pessoas, que muito ame, nem por interesse de dadivas, ou promessas dellas. Deve outrosi o Alcaide Mór do Castello ter abastança de homens, mantimentos, armas e provisões, com que se possa bem defender. E sobre tudo deve ser leal, para que com mais vontade e vigilancia proveja a guarda do Castello, que a seu cargo tem.` },
        { id: 'of1-tlxxiv-1', number: '1', text: `E não devem ser postos Alcaides Móres, senão nos lugares, que tiverem Castello de homenagem, ou onde já houve os ditos Castellos, ou em outros lugares, nos quaes em tempo antigo sempre houve os ditos Alcaides Móres, postoque nelles nunca houvesse Castello.` },
        { id: 'of1-tlxxiv-2', number: '2', text: `E o Alcaide Mór do Castello será obrigado a fazer homenagem, antes que tome posse delle, na fórma que se contém no livro das homenagens, que para isso tem o nosso Scrivão da Puridade. E postoque qualquer Alcaide Mór não faça a dita homenagem, será obrigado, tanto que tomar posse do Castello, a todas as cousas conteúdas nella, assi como se solemnemente a tivesse feito. E não a cumprindo, incorrerá no caso de traição, que incorreria, se em nossas mãos solemnemente a houvesse feito.` },
        { id: 'of1-tlxxiv-3', number: '3', text: `E depois de o Alcaide Mór ter feita a homenagem sobredita, hum Porteiro da Maça lhe irá dar a posse da Fortaleza, e lha entregará perante hum Tabellião publico, e trará instrumento publico, feito pelo dito Tabellião, de como lhe assi entregou a posse. O qual instrumento entregará ao Scrivão da Puridade, que guardará os ditos instrumentos. E o Alcaide Mór fará graça ao dito Porteiro da Maça que lhe assi for dar posse, daquillo, que por bem tiver, com tanto que não desça de dez cruzados. E tomando algum Alcaide Mór posse do Castello e Fortaleza, sem lha dar o Porteiro da Maça, postoque lhe seja dada per auctoridade de Justiça, será nenhuma a tal posse, e de nenhum effeito. E não vencerá rendas algumas da dita Alcaidaria; e se as tiver recebido, as perderá, ametade para quem o accusar, e a outra para nossa Camera. Porém per qualquer maneira que houver a posse da dita Alcaidaria, será obrigado ao conteúdo na dita homenagem sob as penas sobreditas.` },
        { id: 'of1-tlxxiv-4', number: '4', text: `E porquanto não póde o Alcaide Mór escusar ir algumas vezes fóra do Castello, que tem, a outra parte por cousas, que são necessárias, não deve porém fazer isto em tempo, que entenda, que o Castello se póde perder por sua ida. E quando assi houver de ir a algum lugar, deve ir segundo foro de nossos Reinos, convém a saber, deixando hi outro em seu lugar por Alcaide, que seja Fidalgo direitamente de pai e mài, e que não haja feito traição, nem aleive, nem venha de homens, que a houvessem feito; e que seja tal, com quem haja divido de parentesco e de amor grande, de maneira que tenha razão de fiar o Castello delle, como de si mesmo, podendo-se bem haver. E tal como este deve deixar em seu lugar, e dar-lhe as chaves do Castello, e fazer que lhe façam homenagem quantos hi forem, assi como a elle mesmo haviam feito, para guardar o dito Castello bem e lealmente em todas as cousas, até que elle venha. E não podendo haver homem Fidalgo, a que o deixe, deixará por si tal pessoa, que seja Scudeiro, casado, e de idade ao menos de trinta annos, o qual sempre vivirá no Castello. E deixando outro, que não seja da maneira sobredita, perderá as rendas do dito Castello. Porém sempre o dito Alcaide ficará obrigado á homenagem, na fórma e maneira que a deu, ou era obrigado dar, postoque a não désse.` },
        { id: 'of1-tlxxiv-5', number: '5', text: `E quando o Alcaide Mór houver de deixar alguma pessoa por Alcaide e Guarda do Castello, e lhe houver de tomar a homenagem, o fará per auto, feito per Tabellião publico com testemunhas, que ao menos sejam tres, e assinado pela dita pessoa, a que o assi deixar.` },
        { id: 'of1-tlxxiv-6', number: '6', text: `E stando o Alcaide Mór no Castello, se acontecesse, que morresse sem falla, de maneira que não podesse deixar outro de sua mão, deve ficar ao mais proximo parente, que em o Castello houver, se for de idade, e tal homem, que seja para isto. E se tal homem hi não acharem, devem fazer os que stiverem no Castello, Alcaide, o melhor homem, que no Castello for para o ter; e nos devem logo screver, que provejamos de Alcaide, como for nossa mercê; e todavia o devem buscar muito leal e muito amigo do Senhor do Castello. E tal Alcaide, como este, he obrigado fazer e guardar e cumprir todas as cousas em guarda do Castello, assi como acima são ditas.` },
        { id: 'of1-tlxxiv-7', number: '7', text: `E toda a pessoa, que for encarregada da guarda do Castello, ou houver delle posse, per qualquer modo que seja, será obrigado fazer homenagem na fórma, em que a faz o Alcaide Mór.` },
        { id: 'of1-tlxxiv-8', number: '8', text: `Nenhum Alcaide Mór tome sobre si preso, que sté na cadea do Castello, ou na cadea da villa, postoque fóra do Castello sté; nem o tome da mão de qualquer pessoa, que tenha poder de prender, ora seja de pouca substancia, ora de muita, sob pena de pagar cincoenta cruzados para a parte, que accusar, ou demandar o preso, ou para as despesas da Relação, se não tiver parte. E pelo mesmo feito, perderá todos os direitos e poder, que tiver na cadea, e não poderá pôr nella mais Carcereiro, nem haver carceragens, nem outra cousa, que na dita cadea lhe pertencer. E por o mesmo feito fazemos mercê per esta Ordenação da tal cadea á cidade, ou villa, para em vida do dito Alcaide Mór os Juizes e Officiaes porem nella Carcereiro, e levarem para o Concelho as carceragens, como o tal Alcaide Mór fazia. E lhes mandamos, que logo tirem o Carcereiro, que stiver posto pelo tal Alcaide Mór. E ponham em seu lugar outro, que seja fiel e seguro, e arrecade para o Concelho as ditas carceragens, e não consintam mais o Alcaide Mór entender em cousa da dita cadea.` },
        { id: 'of1-tlxxiv-9', number: '9', text: `E postoque os Juizes, ou outras Justiças requeiram, que os Alcaides Móres lhes tomem algum preso, não o poderão tomar, salvo se o Juiz vir, que he pessoa poderosa, e que corre risco star na cadea da villa. E se o Alcaide Mór tiver no Castello Torre, em que o possa ter seguramente, neste caso vendo que he assi como o Juiz diz, e requerendo-lhe elle, o poderá tomar, para o ter preso em ferros na dita Torre; e trazendo-o fóra da Torre com ferros, ou sem elles incorrerá nas penas acima declaradas. E as pessoas, que ficarem em lugar do Alcaide Mór, que tomarem os presos nos ditos casos, incorrerão em pena dos cincoenta cruzados. E bem assi os Alcaides Móres, que os deixarem em seu lugar, incorrerão nas mais do paragrapho acima.` },
        { id: 'of1-tlxxiv-10', number: '10', text: `E em aquelles lugares, em que os Alcaides Móres são obrigados pôr Carcereiros, quando fugir o Carcereiro, ou per outro qualquer modo ficar o dito Officio vago, os Juizes requeiram logo ao Alcaide Mór, que dê outro. E não o dando do dia, que lho requererem, a dez dias, os Juizes e Officiaes ponham então outro á custa do dito Alcaide Mór.

Repairos dos Castellos.` },
        { id: 'of1-tlxxiv-11', number: '11', text: `E os Alcaides Móres, que tiverem Castellos de juro, serão obrigados fazer e repairar nelles todo o aposento necessário para a vivenda do Alcaide Mór, e assi strebarias, atafonas, fornos, casas de Armazens e de mantimentos, telhados de Torres, portas de Fortaleza, trancas, ferrolhos, fechaduras, barreiras, baluartes, repairos de cisternas e poços, e quaesquer danificamentos de muros, barreiras e Torres, e assi de amêas e peitoris. E caindo Torre, ou lanço de muro, baluarte, ou barreira, o povo lhe dará servintia, e o mais fará o Alcaide Mór á sua custa.` },
        { id: 'of1-tlxxiv-12', number: '12', text: `E os que não tiverem os Castellos de juro, serão obrigados a repairar todas as cousas sobreditas, e as entregar no stado, em que lhes foram entregues, tirando muros, barreiras, baluartes e Torres: e quando assi repairarem as sobreditas cousas, que são obrigados, o povo lhes dará a servintia.` },
        { id: 'of1-tlxxiv-13', number: '13', text: `E o nosso Porteiro de Maça, quando der posse de Castello ao Alcaide Mór, requererá aos Juizes, que com hum Tabellião vão ver o Castello, e screvam como as ditas cousas stão ao tempo, que lhe entrega a posse. E do instrumento, que o Porteiro ha de trazer, ficará o traslado no livro da Camera. E no dito instrumento virá certidão de como o traslado d'elle fica nella. E bem assi virá no dito instrumento o traslado do assento, que na Camera stava, de como o Castello e cousas sobreditas stavam ao tempo, que se fez a derradeira entrega d'elle, e como então stá, para se ver, se o Alcaide Mór pas- sado cumprio com o que era obrigado. E achando-se que não deixou o Castello como devia, se pagará e concertará tudo á sua custa.` },
        { id: 'of1-tlxxiv-14', number: '14', text: `E os Juizes dentro de quinze dias do dia, que tomarem posse de seus Julgados, vão ver as Fortalezas da cidade, villa, ou lugar; e achando que não stão concertadas e repairadas, como os Alcaides Móres são obrigados, assi as de juro, como as que o não forem, não lhes deixarão arrecadar as rendas da Alcaidaria, nem correr aos seus Alcaides, até satisfazerem com suas obrigações: e as rendas se arrecadarão para repairo dos ditos Castellos. E a villa proverá de Alcaide pequeno, que haja de correr a terra, em quanto o Alcaide Mór não cumprir com sua obrigação. E o Corregedor da Comarca e o Provedor dos Orfãos e Residuos, quando entrarem nos ditos lugares, antes que se d'elles vão, irão aos Castellos, e farão em todo cumprir esta Ordenação. E os Juizes, Corregedores e Provedores, que pela dita maneira não proverem os Castellos, ou que provendo-os, e achando que não stão como devem, não derem á execução esta Ordenação, sejam condenados cada hum em vinte cruzados, ametade para os Captivos, e a outra para quem accusar, e em dous annos de degredo para Africa.

Direitos dos Alcaides Móres.` },
        { id: 'of1-tlxxiv-15', number: '15', text: `Ao Alcaide Mór pertence haver todas as carceragens dos presos, e todas as armas, que á Alcaidaria forem julgadas, e as penas d'ellas, que são duzentos réis; dos quaes ametade he para o Alcaide Mór, e a outra para quem as coutar, salvo se em alguns casos speciaes forem ordenadas outras penas.` },
        { id: 'of1-tlxxiv-16', number: '16', text: `Item, levará o Alcaide Mór ametade das armas e das penas, que com ellas houverem de pagar, sendo as ditas penas de duzentos réis. E sendo de mór quantia, não levará mais de cem réis, como se dirá no Livro quinto, no Titulo 80: Das armas, que são defesas. E isto quando forem coutadas pelo Alcaide pequeno, ou per seus homens, e bem assi pelos Meirinhos da Corte, ou da Comarca, ou pelos homens de cada hum d'elles, quando se coutarem no lugar, onde Nós não stivermos, nem a Casa da Supplicação: e a outra ametade será dos ditos Meirinhos e seus homens. E no lugar, onde Nós stivermos, ou a Casa da Supplicação, as armas, que assi coutarem, e as penas dellas serão dos ditos Meirinhos e seus homens.` },
        { id: 'of1-tlxxiv-17', number: '17', text: `Item, haverá para si todas as penas pecuniarias dos barregueiros casados e de suas barregãs, que são mil réis de cada quarenta mil, que o barregueiro tiver de fazenda, tirada a parte de sua mulher; e a este respeito do mais e do menos: ou tres mil réis, quando a quarentena não chegar a elles. E a sua barregã pagará ametade de quanto a elle montar de pagar, ou dous mil réis quando ametade da quarentena do barregão a elles não chegar. E assi haverá todas as penas, que hão de pagar as barregãs dos Clerigos e Frades, e outras pessoas Religiosas, que são dous mil réis. E isto haverá lugar, quando o Alcaide Mór accusar e demandar as ditas pessoas, e houver contra ellas sentenças per si, ou per outrem. E sendo ellas demandadas pelo Alcaide pequeno, ou per cada hum dos seus homens, ou per qualquer outra pessoa, haverá o Alcaide Mór sómente a terça parte das ditas penas, e as duas partes serão para o accusador.` },
        { id: 'of1-tlxxiv-18', number: '18', text: `Item, ha de haver para si a terça parte da pena, que hão de pagar os que forem excommungados, sendo por isso presos, segundo a fórma de nossa Ordenação.` },
        { id: 'of1-tlxxiv-19', number: '19', text: `E bem assi ha de haver cento e oito réis de cada força, que for julgada, e que elle restituir per mandado do Juiz, ou de outra pessoa, que poder tenha de o mandar.` },
        { id: 'of1-tlxxiv-20', number: '20', text: `Item, de todo o ouro, ou prata, e dinheiro, que for achado nos jogos defesos, haverá ametade. E mais as coimas de todas as tavernas que forem achadas abertas depois do sino de recolher até manhã clara. E haverá mais das penas, que forem postas pelos homens da Alcaidaria per mandado da Justiça ás mulheres, que são useiras de bradar, cento e oito réis de coima por cada vez, que nella cairem.` },
        { id: 'of1-tlxxiv-21', number: '21', text: `Outrosi ha de haver as coimas, que são postas aos que são achados tomando agoa, ou lastro em barcas e bateis depois do sino de recolher, que são, por cada vez que forem achados, cento e oito réis, e mais perderão toda a louça, que trouverem para tomar a dita agoa. E haverá mais todas as armas, que forem achadas, levando-as algum Mouro em algum navio, que vá para além mar, afóra huma, que levar para defensão de seu corpo, e se obrigue tornar esta arma, e dé a isso fiadores. E não a tornando, pagarão por ella tres armas, ou tres vezes aquillo, que valer.` },
        { id: 'of1-tlxxiv-22', number: '22', text: `Item, ha de haver todo o pescado, que se matar aos Domingos e Festas de Nosso Senhor, e de Nossa Senhora e dos Apostolos, e nas noites entre as vesperas e os dias dos sobreditos Santos. E isto se não entenderá nos pescados, de que os pescadores tiverem licença do Santo Padre, ou dos Prelados, que os possam matar nos ditos dias.` },
        { id: 'of1-tlxxiv-23', number: '23', text: `E todo o Mouro, que se forrar para se ir fóra da terra, e pagar a dizima, pagará ao Alcaide-Mór a redizima.` },
        { id: 'of1-tlxxiv-24', number: '24', text: `E de qualquer navio que for achado depois do sino de recolher, tomando carrega, ou descarregando, ou mettendo homens, mulheres, pescado, ou outra qualquer cousa, haverá cento e oito réis por cada vez, que assi for achado.` },
        { id: 'of1-tlxxiv-25', number: '25', text: `E poderá o Alcaide Mór pôr hum Seudeiro, que continuadamente ande com o Alcaide pequeno, assi de noite como do dia: E que requeira ao dito Alcaide, que seja diligente em requerer todos os direitos, que pertencem á Alcaidaria: e que se alguns direitos se perderem por sua falta, ou neglígencia, elle seja obrigado a os pagar ao Alcaide Mór. E poderá mais pôr per suas Cartas dous Serviães, hum na Alcaidaria da villa, e outro na dos montes, onde a houver, que andem continuadamente com os ditos Alcaides das villas e dos montes.` },
        { id: 'of1-tlxxiv-26', number: '26', text: `E quem quer que procurar em cousa, que toque á Alcaidaria, se não tiver auctoridade nossa para procurar em Juizo, e procuração da parte, a que pertencer, pague novecentos réis, além de incorrer nas penas postas aos que procuram sem nossas cartas, que são declaradas no Titulo 48: Dos Adrogados e Procuradores.` },
        { id: 'of1-tlxxiv-27', number: '27', text: `E mandamos, que todo o conteúdo neste titulo se cumpra e guarde, como nelle he declarado: salvo se per cartas ou privilegios nossos, ou dos Reis nossos antecessores stiver em costume de se fazer o contrario: porquanto em tal caso queremos que se guardem as ditas Cartas, ou privilegios.` },
      ],
    },
    {
      id: 'titulo-lxxv',
      title: `LXXV. Dos Alcaides pequenos das cidades e villas`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxv-preambulo', number: 'Preâmbulo', text: `Os Alcaides pequenos serão feitos per esta maneira. Os Senhores dos lugares, ou Alcaides Móres presentarão aos Juizes e Véreadores em Camera tres homens bons, casados na cidade, villa, ou lugar, que sejam abonados, naturaes de nossos Reinos; e os Juizes e Véreadores escolherão hum daquelles que para ello seja pertencente. E não sendo os Juizes e Véreadores contentes de nenhum delles, o Senhor da terra, ou Alcaide Mór lhes apresentará outros tres, que sejam mais idoneos, que os que jà presentou, e lhes não foram recebidos. E não sendo os Juizes e Véreadores contentes de nenhum dos tres, que á segunda vez lhes foram apresentados, então seja o Senhor do lugar, ou Alcaide Mór obrigado a apresentar outros tres. E destes nove serão os Juizes obrigados tomar hum, o mais idoneo delles, o qual servirá o dito Officio per tres annos, e mais não; os quaes acabados, se fará outro na maneira sobredita. E servindo mais que os ditos tres annos, ou servindo sem ser presentado e recebido na sobredita maneira, mandamos que seja degradado dous annos para Africa, e que nunca mais possa servir de Alcaide. E nas mesmas penas incorrerão os Juizes, que deixarem servir o dito Alcaide, passados os tres annos, ou não sendo presentado, como dito he. E não tolhemos, depois que passarem outros tres annos, acabados os annos que elle servio, que possa ser elegido para outros tres annos.` },
        { id: 'of1-tlxxv-1', number: '1', text: `Porém os Alcaides Móres serão avisados, que nas ditas apresentações não usem de algum engano, ou má cautela, apresentando pessoas não idoneas para tal Officio, para lhes ser recebido aquelle, que quizerem favorecer, porque fazendo nisso o que não se deva, Nós daremos tal provisão, que se faça como deve.` },
        { id: 'of1-tlxxv-2', number: '2', text: `Outrosi, nos lugares onde o Alcaide per Nós ha de ser posto, os Juizes e Véreadores e homens bons escolherão hum homem bom para isso pertencente, e nolo enviarão com sua Carta para o confirmarmos, ou pormos outro, qual virmos que cumpre, o qual servirá tres annos, e mais não, sob as penas sobreditas. E se antes quizerem mandar pela confirmação ao Corregedor da Comarca, elle lhes poderá dar Carta de confirmação.` },
        { id: 'of1-tlxxv-3', number: '3', text: `E nos lugares, onde per Foral o Alcaide se ha de pôr pelo Concelho, sem o apresentarem ao Alcaide Mór, usem do dito Foral, como sempre usaram, servindo porém tres annos, e mais não, sob as penas sobreditas. Porém não he nossa tencão de por isto tolher aos Concelhos seu direito, onde a eleição dos Alcaides a elles pertence, e o Alcaide Mór recebe o per elles presentado; porque onde os Concelhos stão em posse de assi o fazer, mandamos que assi se faça. E antes de o Alcaide servir, lhe será em Camera dado juramento sobre os Sanctos Evangelhos, que bem e verdadeiramente sirva seu Officio, e guarde todas as cousas nesta Ordenação conteúdas, e que tenha segredo nas cousas, que lhe forem encarregadas ter bem de Justiça, guardando em todo a Nós, nosso serviço, e ao povo seu direito. E antes que lhe dêm o juramento, dará fiança, para que se algum dano fizer com o Officio, se haver pela dita fiança até a quantia della; a qual será nas cidades trinta mil réis, e nas villas vinte, e nos Concelhos de terras chãs dez mil. E os Juizes e Officiaes da Camera, que lhe deixarem servir o Officio sem a dita fiança, pagará cada hum oito mil réis, ametade para quem accusar, e a outra para a nossa Camera.` },
        { id: 'of1-tlxxv-4', number: '4', text: `E tendo necessidade de infirmidade, ou outra semelhante, porque per si não possa servir, o notifique aos Juizes e Officiaes da Camera, e com seu acordo e aprazimento do Alcaide Mór, ponham outro para ello pertencente, que seu lugar tenha, até que seja fóra da dita necessidade, e mais não. E o Alcaide, que em outra maneira o poser, perca o Officio, e pague dous mil réis. E quem o servir, pagará outro tanto para quem accusar: e mais haverá aquella pena, que mereceria qualquer do povo, que sem auctoridade alguma servisse o dito Officio. E esta mesma pena haverá o que servir per mandado do Alcaide Mór sem auctoridade do Juiz e Officiaes. E não respondam a esses, que assi pozerem, em cousa alguma, nem façam per seus mandados, nem os hajam por Alcaides. E se o Alcaide Mór o pozer, façam-o saber a Nós, para lho estranharmos, como houvermos por bem.

Já se vê que aqui a expressão homens bons se toma na acepção de simples cidadãos.

Tanto a edição Vicentina como as outras que consultámos usão dos verbos presentar e apresentar no mesmo paragrafo.

Tal era o ciume da Realeza.

Segundo Pegas no respecto Com., para se firmar esse direito consuetudinario, bastava que por dez annos se houvesse praticado.` },
        { id: 'of1-tlxxv-5', number: '5', text: `E mandamos, que nenhum Alcaide, nem Meirinho faça tronco, nem cadêa onde nunca a houve. E fazendo o contrário maliciosamente, seja degradado hum anno para Africa, e pague ás partes toda a perda e dano, que por isso receberem.` },
        { id: 'of1-tlxxv-6', number: '6', text: `E nenhum Alcaide, nem Meirinho, qualquer que seja, advogará, nem procurará por pessoa alguma no lugar, onde servir o Officio, nem aceitará procuração para por elle sobstabelecer, salvo nos seus feitos, ou das pessoas, que viverem continuadamente com elles em suas casas, sob pena de perdimento dos Officios.` },
        { id: 'of1-tlxxv-7', number: '7', text: `E no lugar, onde for Alcaide, não será Rendeiro das armas, nem da renda da Alcaidaria, nem de outra nossa, nem de outra pessoa, sob pena de perder o Officio e ser preso, em quanto o houvermos por nosso serviço.` },
        { id: 'of1-tlxxv-8', number: '8', text: `E mandamos aos Alcaides, que assi de noite, como de dia, guardem bem as cidades, ou villas, com os homens jurados, que lhes forem dados pelos Officiacs do Concelho, naturaes, ou moradores, onde per Foral forem obrigados a lhos dar. E quando de noite andarem, tragam sempre hum Tabellião, que o Juiz lhes dará cada noite per distribuição, e o constrangerá para isso (onde não houver Scrivão para isto deputado); o qual dará fé e testemunho das cousas, que o Alcaide fizer e achar, de maneira que por sua falta e negligencia não se faça mal, furto, nem roubo algum; porque fazendo-se o contrário, pagal-o-hão per seus bens.` },
        { id: 'of1-tlxxv-9', number: '9', text: `E em cada noite, quando tangerem á Ave Maria, sejam todos juntos em casa do Alcaide, e elle e o Scrivão lhes assinem, como hão de guardar a cidade, ou villa, e assi os ditos homens a guardem de dia, segundo fôr acordado pelo Alcaide e Scrivão. E não se apartem a andar de noite, até que cheguem a casa do Alcaide, e que per elle e pelo Scrivão lhes seja dito a maneira como hão de fazer. Os presos, que prenderem, digam ao Carcereiro o porque cada hum for preso, para o guardar, e saber a quem ha de requerer seu livra-mento. E o homem do Alcaide, que cada huma das sobreditas cousas não fizer, ou for negligente, por a primeira vez perca o mantimento de oito dias, e por a segunda de hum mez, e pola terceira seja preso trinta dias.

Prisões.` },
        { id: 'of1-tlxxv-10', number: '10', text: `E prenderá per mandado dos Julgadores, e de outra maneira não, salvo achando algum em fragante malefício, ou sendo-lhe requerido per qualquer pessoa, em algum arroido, ou sendo-lhe mostrada querela com summario obrigatorio, não stando o Juiz no lugar ao tal tempo, ou alguma pessoa suspeita de noite, ou com armas defesas, ou sem ellas depois do sino de recolher; e os que elle per si prender, leve-os perante o Juiz, antes que vão á cadea. Porém, se for de noite, ou a taes horas, que o não possa achar, ou não for na cidade, ou for tal pessoa o preso, que seria perigosa cousa de o trazer per a villa, leve-o á prisão, que tiver em sua casa, ou alguma outra que para isso seja assinada per o Alcaide Mór. E venha logo ao Juiz pela manhã, se o á noite prender; e se merecer de ser preso, seja-o, e se não merecer, soltem-no sem carceragem. Porém no caso, onde for preso por ser achado depois do sino de recolher, e não tiver outra pena senão de dinheiro, se logo pagar, e o Juiz o mande soltar, sem ir á cadea, e sem pagar carceragem. E se os não trouxer perante os Juizes, ou os não soltar per seus mandados, os Juizes lhe façam tudo pagar per seus bens.` },
        { id: 'of1-tlxxv-11', number: '11', text: `E o mandado do Julgador, per que o Alcaide ha de prender, será em scripto, e assinado per elle; porque depois, negando o Juiz que o não mandou prender, não será recebida ao Alcaide prova de testemunhas. E isto não haverá lugar, quando o Julgador mandar ao Alcaide, que lhe prenda hum homem ou mulher, e que o traga perante elle, porque neste caso não será necessario Alvará, mas sómente quando o houver de metter na cadêa.` },
        { id: 'of1-tlxxv-12', number: '12', text: `Item, mandamos que nenhum Alcaide, nem Meirinho, nem seus homens soltem pessoa, que presa tiverem, ou prenderem Pegas diz que esta prisão he a que se chama — custodia.

per mandado da Justiça, ou por o acharem commettendo algum crime, sem mandado special da Justiça, que poder tenha para o mandar soltar. E se o soltar, e se perder à Justiça, ou alguma outra parte receber por a dita soltura perda, ou dano, o Alcaide, Meirinho, ou seus homens, ou aquelle, que o soltar, seja obrigado à emenda, se for feito de emenda, e os Juizes o façam emendar; e sendo feito crime, seja logo preso, e façam delle justiça, e haverão aquellas penas, que são postas ao Carcereiro, que solta preso sem mandado da Justiça. E sendo Alcaide Mór de Castello, não o prendam, e o emprazarão que em certo tempo pareça em nossa Corte, para mandarmos o que houvermos por bem.` },
        { id: 'of1-tlxxv-13', number: '13', text: `E o Alcaide, quando assi prender alguma pessoa, ou for na prisão della, fará fazer o auto do habito e tonsura, segundo diremos no quinto Livro, no Titulo 121: Que ao tempo da prisão, etc.` },
        { id: 'of1-tlxxv-14', number: '14', text: `Mandamos aos Alcaides e Meirinhos, que não tragam diante de si o Scrivão e os homens, quando de noite correrem, sob pena de suspensão dos Officios até nossa mercê, e de pagarem por cada vez, que o fizerem, vinte cruzados, ametade para quem os accusar, e a outra para os Captivos.` },
        { id: 'of1-tlxxv-15', number: '15', text: `E os Alcaides da cidade de Lisboa, quando prenderem algumas pessoas de dia, ou de noite, por qualquer caso que seja, as poderão levar perante os Corregedores da Corte, ou os Corregedores, ou Juizes do Crime da dita cidade, segundo lhes parecer que mais conveniente e seguramente as podem levar, sem os ditos Corregedores lho poderem defender. E quando prenderem per mandado de qualquer Julgador, as levarão perante o Julgador, que o tal mandado passou. E não sendo o dito Julgador presente na cidade, as levarão perante o outro Julgador seu companheiro. E sendo ambos absentes, a hum dos Corregedores da Corte. E tendo os ditos Alcaides mandados dos Corregedores da Corte e dos da cidade, em tal caso os levarão primeiro ao Corregedor da Corte.` },
        { id: 'of1-tlxxv-16', number: '16', text: `E quando os Alcaides, ou Meirinhos fôrem em seguimento de algum delinquente, para o prenderem, e se lhe acolher a casa de alguma pessoa de grande stado, assi Ecclesiasticos, como secular, terão a ordem, que dissemos no titulo 73: Dos Quadrilheiros.

Homens dos Alcaides.` },
        { id: 'of1-tlxxv-17', number: '17', text: `E os homens, que o Alcaide houver de trazer, sejam presentados aos Juizes e Officiacs, e lhes dêm juramento na Camera, e scriptos no livro da Véreação, para serem conhecidos por homens da Justiça, e como taes os temerem. E a estes homens pagará e dará o Alcaide Mór seus mantimentos nos lugares, onde os Alcaides Móres são obrigados de os dar. E não o fazendo assi, os Juizes tomem tantas das suas rendas, per que logo sejam pagos.` },
        { id: 'of1-tlxxv-18', number: '18', text: `Os Alcaides não trarão homens comsigo, salvo os que tiverem juramento, e forem scriptos no livro do Concelho. Nem trarão elles, nem os Alcaides Móres homens daninhos; e trazendo-os, mandamos aos Juizes que saibam quaes isto fazem, e mandem logo requerer ao Alcaide, que emende o dano, e pague a coima em dobro pelos seus homens, ou lhos entreguem, para fazer delles cumprimento de justiça. E não os entregando, façam pagar pelos bens do dito Alcaide em dobro o dano à parte, e a coima ao Concelho e ao Rendeiro, sob pena de a pagarem os ditos Juizes per seus bens.

Diligencias.` },
        { id: 'of1-tlxxv-19', number: '19', text: `Outrosi, todo o Alcaide será diligente per si e per seus homens guardar as audiencias, e trazer os presos perante os Juizes, quando lhe mandarem, sem por isso lhes levar dinheiro. E se os não trouxer à audiencia, ou os não soltar per seus mandados, os Juizes lhe façam todo pagar per seus bens.` },
        { id: 'of1-tlxxv-20', number: '20', text: `E bem assi será diligente em guardar os Almotacés e açougues e praça de tal maneira, que não entrem nos açougues, nem tomem a carne, nem o pescado e outras cousas, que à praça vem, per força, sob pena de as pagarem a seus donos, e não haverem o que delles devem levar por o foro da cidade.` },
        { id: 'of1-tlxxv-21', number: '21', text: `E não penhorará, nem constrangerá pessoa alguma por divida, nem por outra cousa, salvo se lhe for mandado pelos Segundo o primeiro Decreto, os homens dos Alcaides podião ser negros livres ou captivos.

Juizes, ou per o Almoxarife, ou per outro algum, que para isso haja nossa auctoridade, per seu mandado assinado per o dito Official, ou levando a sentença de condenação. E passando a execução de mil reis, não a fará sem Scrivão. E fazendo o contrario, pagará de pena quinhentos reis, ametade para quem o accusar, e a outra para os Captivos, e mais pagará á parte toda a emenda.` },
        { id: 'of1-tlxxv-22', number: '22', text: `Item, se o Alcaide for mandado per algum Julgador, que ponha segurança entre algumas pessoas, entre quem houver alguma inimizade, o fará com diligencia, sem por isso levar cousa alguma. E se o assi não fizer, e por isso se seguir algum mal, seja o dito Alcaide a isso obrigado, o qual nunca porá a dita segurança sem mandado da Justiça.

Penas e direitos.` },
        { id: 'of1-tlxxv-23', number: '23', text: `O Alcaide não deixe trazer a pessoa alguma as armas, que em todo o tempo são defesas, nem as outras no tempo, que forem defesas, e as tome e coute ás pessoas, que as trouxerem, segundo diremos no Livro quinto, no Titulo 80: Das armas que são defesas. Nem dê licença e lugar a pessoa alguma, postoque seja do Alcaide Mór, e com elle viva, que as traga. Nem faça avença por as coimas e penas, que ha de haver das pessoas, a que são defesas, antes da sentença, sob pena de pagar, se for Alcaide Mór, dous mil reis para a Piedade: e se for o Alcaide pequeno, pagará mil reis por cada vez que o contrario fizer. E depois da sentença, as poderá quitar uma vez sómente. E se outra vez as quitar á mesma pessoa, pagará a pena em dobro, e será a dita pena applicada aos Captivos. E mandamos aos Tabelliães, sob pena de perderem os Officios, que screvam e dêm em stado aos Juizes, quaes são a pessoas, que assi trazem as ditas armas per licença do Alcaide, ou sabendo-o elle, ou a quem as vio, e não as quiz coutar, e os Juizes lhe façam logo pagar a pena sobredita, e não o fazendo assi, o pagarão per seus bens. E da obra, que os Juizes fizerem, assi o dêm ao Corregedor da Comarca, para ver como se deu á execução, ou a fazer elle executar, sob pena de a pagar em dobro. E as que em todo o tempo são defesas, ou as outras, trazendo-as de noite a deshoras, ou de dia, fazendo com ellas o que não devem, as coutará, e as perderão, e serão demandadas, sob as penas e clausulas sobreditas.` },
        { id: 'of1-tlxxv-24', number: '24', text: `Item, todas as coimas, ou penas, que o Alcaide houver de haver das pessoas, que achar em coima, assi como os que fazem forças, e elle as for restituir per mandado da Justiça, ou lançam de noite agoas, ou outras semelhantes a estas, demande-as do dia, que forem feitas, a tres dias, os quaes passados, as não poderá mais demandar. E quanto ás armas, as poderá demandar até oito dias, como diremos no Livro quinto, Titulo 80: Das armas que são defesas.` },
        { id: 'of1-tlxxv-25', number: '25', text: `Item, os direitos, que ha de haver dos Carniceiros e de outras pessoas, os requererá no mesmo dia. E não o fazendo assi, os não poderá depois demandar, nem os Juizes o ouvirão sobre elles.` },
        { id: 'of1-tlxxv-26', number: '26', text: `Outrosi o Alcaide e seus homens não levarão dinheiro, nem outra cousa de preso algum, polo levar onde o hajam de ouvir. E o que o contrario fizer, pola primeira vez pague o tresdobro do que levar: e pola segunda noveado para os Captivos: e pola terceira o Alcaide perca o Officio, e seja preso, emquanto Nós o houvermos por nosso serviço. E se for algum de seus homens, seja logo açoutado pela villa.` },
        { id: 'of1-tlxxv-27', number: '27', text: `E servindo de Carcereiro, guardará o Regimento dos Carcereiros das cidades e villas, e o das carceragens da Corte.` },
        { id: 'of1-tlxxv-28', number: '28', text: `Se o Alcaide fizer per si, ou per outrem, pedido de pão, ou de cevada, ou de outras cousas, no lugar e seu termo donde he Alcaide, ou tomar, ou levar alguma cousa, ou receber acostamento, ou tença de alguma pessoa do dito lugar, ou de seu termo, incorra nas penas, que diremos no Livro quinto, no Titulo 71: Dos Officiaes del Rei, que recebem serviços. E não se escusará das ditas penas, per dizer e provar que lho deram por suas vontades, sem lho elle pedir. Mas como quer que se achar, que levou alguma cousa, sem por ella pagar o preço, que razoadamente valer na terra, haverá as ditas penas.` },
      ],
    },
    {
      id: 'titulo-lxxvi',
      title: `LXXVI. Dos Alcaides das Sacas`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxvi-preambulo', number: 'Preâmbulo', text: `Os Alcaides das Sacas hão de ser postos per nossas Cartas nos lugares do extremo, e não nos outros, que stão dentro do Reino. Aos quaes mandamos, que com muita diligencia e fidelidade cumpram o que se contém nas Ordenações, feitas contra os passadores dos gados e cousas defesas.` },
        { id: 'of1-tlxxvi-1', number: '1', text: `E requeiram aos Juizes das villas e lugares das suas Comarcas, que mandem aos Tabelliães, que lhes dêm em rol, per elles assinados, todos os passadores de gado e cousas defesas, que acharem culpados nas inquirições devassas e autos, que tiverem, para os accusarem, segundo fórma de nossas Ordenações, dos puntos fórma as ditas cousas defesas. E os culpados irão responder per as ditas accusações perante os Juizes dos lugares, per onde passarem as ditas cousas defesas, postoque morem em outras villas e lugares, por alongados que sejam. Perante os quaes Juizes serão demandados pelos ditos Alcaides das Sacas judicialmente, tanto que presos forem. E a parte condenada poderá appellar, que quizer da sentença dos Juizes; os quaes lhe receberão appellação. E não querendo a parte appellar, os Juizes appellarão por nossa parte: e virão as appellações aos Juizes de nossos feitos.` },
        { id: 'of1-tlxxvi-2', number: '2', text: `E não podendo os Alcaides das Sacas per si prender e tomar as cousas defesas, que alguns passadores, ou outras pessoas passarem contra fórma de nossas Ordenações, quaesquer Justiças e pessoas, a que pertencer, e a que pelos ditos Alcaides for requerido, mandem com elles, e vão, se cumprir, para a prisão dos taes, e toma-dia do que passarem e levarem defeso, e para tudo o que para execução do que neste caso mandamos, e lhes os ditos Alcaides requererem da nossa parte, o que farão com muita diligencia. E qualquer dos sobreditos, que o assi não cumprir, incorra em pena de cincoenta cruzados, para o Alcaide das Sacas, ou Official dellas, que lhe o tal requerimento fizer, e mais haverá outra pena, que nos bem parecer. E os ditos Alcaides das Sacas tomarão instrumentos públicos dos requerimentos, que ás ditas Justiças fizeram, e de como foram negligentes, para provermos na execução destas penas. E esta pena se não entenderá nos Alcaides Móres, nem Corregedores, porque quanto a elles, proveremos, como houvermos por bem, quando forem culpados, o que delles não esperamos. E encommendamos-lhes, que dêm aos Alcaides das Sacas todo o favor e ajuda, que podérem. E de como o elles fizerem, nol-o farão os ditos Alcaides saber, para castigarmos, como nos bem parecer, os que nisso não servirem bem.` },
        { id: 'of1-tlxxvi-3', number: '3', text: `E damos poder aos Alcaides Móres das Sacas, das Comarcas, onde os houver, que provejam sobre os Alcaides pequenos dellas, e saibam se cumprem as Ordenações, que falam nos passadores de cousas defesas. E achando que algum o não faz, como he obrigado, o possam suspender do Officio e prender, confórme a qualidade de sua pessoa e da culpa. E nos farão logo saber as culpas e erros, em que os acham, para mandarmos entender em seu castigo e despacho. E lhes damos outrosi poder, para com os Juizes e Officiaes da villa, ou lugar, de que forem os Alcaides suspensos, elegerem pessoas aptas, que sirvam por elles, em quanto forem suspensos, e nós os não provermos: ás quaes pessoas será dado juramento dos Evangelhos, que sirvam bem, e guardem em todo nossas Ordenações.` },
        { id: 'of1-tlxxvi-4', number: '4', text: `E mandamos aos Alcaides das Sacas e a todas as Justiças, que tenham cuidado de saber, se se guardam as Ordenações sobre os passadores do gado e cousas defesas, e façam dar á execução contra os culpados as penas nellas conteúdas.

O Alcaide das Sacas assim se denominava da palavra Saca ou Sacca, que em arabe significa direito cobrado nas Alfandegas das fazendas ou generos que se exportão. A saca quer tambem dizer: extracção, exportação.` },
      ],
    },
    {
      id: 'titulo-lxxvii',
      title: `LXXVII. Dos Carcereiros das cidades e villas, e das carceragens`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxvii-preambulo', number: 'Preâmbulo', text: `Os Carcereiros, ou Alcaides, que carrego tiverem de cadeas, ou prisões publicas, serão diligentes em levarem os presos às audiencias, e os soltarem, quando lhes for mandado pela Justiça, que para isso poder tenham. E não o fazendo assi, os Juizes façam pagar aos ditos presos o dano, que por isso receberem, pelos bens dos ditos Alcaides e Carcereiros.` },
        { id: 'of1-tlxxvii-1', number: '1', text: `E defendemos aos ditos Carcereiros e Alcaides, que não levem serviço algum, nem peita dos presos, nem de outrem, que lhas dê por seu respeito, sob pena de perderem os Officios, e mais serem punidos, segundo o serviço e peita, que levarem.` },
        { id: 'of1-tlxxvii-2', number: '2', text: `Outrosi mandamos aos ditos Alcaides e Carcereiros, que não tragam soltos os presos, nem dêm consentimento, que pessoa alguma, que lhes for entregue preso, ande solto. E o que o contrario fizer, pague por cada vez que trouxer o preso solto, ou o deixar andar solto, tres mil réis. E se for preso por caso, que receria pena de morte, e o trouxer solto, pague dez mil réis. Das quaes penas ametade será para quem o accusar, e a outra para nossa Camera. E se for Alcaide Mór o que assi trouxer os presos soltos, pagará as ditas penas em dobro. E esta mesma pena haverão os Carcereiros, ou Alcaides, que nas villas chãs, ou cercadas tiverem os presos em algumas casas fóra das ordenadas para as cadeas, ou fóra dos Castellos.` },
        { id: 'of1-tlxxvii-3', number: '3', text: `E porque muitas vezes os presos fogem das cadeas e prisões e Castellos, onde stão, por culpa e má guarda dos Alcaides e Carcereiros, de cuja confiança pende grande parte da justiça, determinamos, que se o preso fugir por malicia, ou manifesta culpa do Carcereiro, esse Carcereiro morra por isso, se aquelle, que lhe fugir, for accusado por tal maléficio, que, se provado fosse, deveria morrer. E sendo accusado por outro qualquer maléficio menor, será esse Carcereiro açoutado publicamente e degradado dous annos para Africa. E em todo o caso emendará o dano às partes, que pela dita fugida forem danificadas.` },
        { id: 'of1-tlxxvii-4', number: '4', text: `E postnque o Carcereiro tivesse encommendada a guarda da cadea a alguem, que a guardasse de sua mão, e neste tempo fugisse o preso, não deixará por tanto de haver a pena acima dita. E outra tal pena haverá aquelle, a quem tinha encommendada a cadea, de maneira que ambos haverão igual pena, e hum não será escuso pelo outro.` },
        { id: 'of1-tlxxvii-5', number: '5', text: `E se por fugida de alguns presos ficar na prisão alguma roupa, ou quaesquer outras cousas, não as hajam os Alcaides, Meirinhos, Carcereiros, nem homens seus, mas paguem-se e concertem-se pelas ditas cousas as prisões, ferros e quaesquer danos, que os presos fizeram na dita prisão.` },
        { id: 'of1-tlxxvii-6', number: '6', text: `E defendemos, que nenhum Alcaide nem Carcereiro solte preso algum da prisão, em que o tiver, sem mandado da Justiça. E o que o contrario fizer, se o dito preso stava preso por feito civel, pague às partes todo o dano, que por a tal soltura receberem. E sendo preso por feito crime, se for solto sem peita, prendam logo o Carcereiro ou o Alcaide, que o soltar, e façam delle justiça, dando-lhe a pena, que acima temos dito que haja o Carcereiro, a que foge o preso por sua malicia. Porém, se o que o soltar for Alcaide Mór do Castello, não o prendam, mas façam-o logo saber a Nós, para mandarmos o que nos parecer justiça.` },
        { id: 'of1-tlxxvii-7', number: '7', text: `E quando o Carcereiro, ou Alcaide soltar algum preso por peita, seja presso, e haja a pena, que haveria se furtasse aquillo, que de peita levou, com todas as qualidades, que os furtos tem, á cerca das penas, que por elles se devem dar. E além disso, se a peita não chegar a quantidade, por que deva morrer, haverá mais a pena, que he posta aos Carcereiros, a que fogem os presos por malicia, ou manifesta culpa.` },
        { id: 'of1-tlxxvii-8', number: '8', text: `E todos os Alvarás per que se mandam soltar os presos, sejam scriptos pelo Scrivão do feito, onde o houver, ou pelo Scrivão da Alcaidaria, onde não houver Scrivão do feito. E levará por fazer hum Alvará quatorze réis, e mais não. E em fim de cada hum delies ponha o que o preso ha de pagar de carceragem, para que as carceragens venham a boa recadação.` },
        { id: 'of1-tlxxvii-9', number: '9', text: `E levará de carceragem o que se contém no Titulo 34: Das Carceragens da Corte.` },
        { id: 'of1-tlxxvii-10', number: '10', text: `E o Scrivão da Alcaidaria faça hum livro apartado, em que ponha todas as carceragens, que os presos pagarem, segundo as pagas, que elle pozer nos Alvarás de soltura. E cada semana huma vez concertará esse livro com outro, que tiver o Carcereiro, em que são scriptos os Alvarás com as pagas. Porque per este livro será tomada conta das carceragens ao que as receber.` },
        { id: 'of1-tlxxvii-11', number: '11', text: `E porque ao Officio dos Carcereiros pertencem outras muitas cousas, que aqui não são declaradas, mandamos que guardem e cumpram o Regimento do Carcereiro da Corte, emquanto se a elle podér applicar, sob as penas nelle conteúdas, segundo a differença dos casos.` },
      ],
    },
    {
      id: 'titulo-lxxviii',
      title: `LXXVIII. Dos Tabelliães das Notas`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxviii-preambulo', number: 'Preâmbulo', text: `Em qualquer cidade, villa, ou lugar, onde houver casa deputada para os Tabelliães das Notas, starão nella pela manhão e à tarde, para que as partes, que os houverem mister para fazer alguma scriptura, os possam mais prestes achar.` },
        { id: 'of1-tlxxviii-1', number: '1', text: `Mandamos, que onde houver dous Tabelliães das Notas, ou mais, nenhum delles faca scriptura alguma, sem lhe ser distribuido pelo Distribuidor. E fazendo o contrário, pola primeira vez será suspenso do seu Officio per seis mezes, e pague dous mil réis para quem o accusar: E pola segunda privado delle.` },
        { id: 'of1-tlxxviii-2', number: '2', text: `Outrosi, todos os Tabelliães serão diligentes em guardarem muito bem os livros das Notas em todos os dias de sua vida. E por sua morte seus herdeiros serão obrigados de os entregar per inventario ao successor do Officio; o qual será obrigado de os guardar até quarenta annos, contados do tempo, que as scripturas foram feitas, de maneira que quando forem requeridos para mostrarem as Notas, as mostrem sãs, limpas e encadernadas em pergaminhos, ou o que mais quizerem. E por seu trabalho de as buscar haverão aquillo, que lhes per Nós he taxado, sem pedirem, nem levarem por isso outras dadivas. E se não mostrarem as ditas Notas boas, sãs, e sem duvida alguma e encadernadas, como dito he, todo o dano e perda, que se ás partes disso seguir, pagarão per seus bens, e mais perderão seus Offícios: não tolhendo porém de elles haverem as penas, que per Leis de nosso Reino e Direito devem haver.

Scripturas.` },
        { id: 'of1-tlxxviii-3', number: '3', text: `E serão diligentes, cada vez que fôrem chamados para irem fazer alguns contractos, pela utilidade que póde resultar no público, e ao mesmo Tabellião, ás vezes com um simples traslado de antiquissimas escrituras.

A escritura pública presume-se verdadeira, reunindo as seguintes condições:

2.ª Declaração da cidade, villa, lugar e casa em que houver sido lavrada. Ord. do liv. 1 t. 80 § 7.

3.ª Se os Tabelliães conhecem as partes, ou se são conhecidos das testemunhas dos contractos, ou de outras que sejão fidelidignas, e que assignem a escritura. Ord. do liv. 1 t. 78 § 6.

4.ª Cópia da Procuração ou Procurações não sendo, o contracto assignado pelas proprias partes.

Este requisito observa-se por estylo, em Portugal, em diferentes Províncias do Brasil, e deduz-se das Ords. do liv. 3 t. 29 pr. e t. 60 pr.

Na Côrte, segundo Teixeira de Freitas, o estylo he registrar-se a Procuração em livro diferente da nota, o que nos parece illegal e inconveniente; e em alguns lugares o abuso leva-se mais longe, porquanto nem esse registro se faz, como se nestes casos bastasse sómente a fé do Tabellião.

5.ª Declaração da leitura do contracto, depois de lavrado, perante as partes e testemunhas. Ord. do liv. 1 t. 78 § 4.

6.ª Resolva das emendas, entrelinhas ou palavras riscadas antes das assignaturas, e ainda de quaesquer duvidas. Ord. cit.

7.ª Assignatura das partes ou de uma pessoa a seu ou testamentos a algumas pessoas honradas ou enfermas, e molheres, que razoadamente não possam, nem devam com honestidade ir à dita Casa e Paço dos Tabelliães, que vão logo às casas ou pousadas daquelles, a cujo requerimento fôrem chamados.` },
        { id: 'of1-tlxxviii-4', number: '4', text: `E screverão em hum livro, que cada hum para isso terá, todas as Notas dos contractos, que fizerem. E como forem scriptas, logo as leam perante as partes e testemunhas, as quaes ao menos serão duas. E tanto que as partes outorgarem, assinarão ellas e as testemunhas. E se cada huma das partes não souber assinar, assinará por ella huma pessoa, ou outra testemunha, que seja além das duas, fazendo menção, como assina pola parte, ou partes, porquanto ellas não sabem assinar. E se em lendo a dita Nota, for emendada, accrescentada per entrelinha, mingoada, ou riscada alguma cousa, o Tabellião fará de tudo menção no fim da dita Nota, antes das partes e testemunhas assinarem, de maneira que depois não possa sobre isso haver duvida alguma.` },
        { id: 'of1-tlxxviii-5', number: '5', text: `E quando forem requeridos para fazer alguma scriptura de qualquer contracto, ou firmidão entre partes, não as screvam em canhenhos, nem per emmentas, mas as notem logo em seus livros de Notas, como dito he. E as não dem, nem passem sob seu signal público, nem privado, até serem perante as partes lidas e assinadas.` },
        { id: 'of1-tlxxviii-6', number: '6', text: `E se os ditos Tabelliães não conhecerem algumas das partes, que os contractos querem firmar, não façam taes scripturas: salvo se as partes trouxerem duas testemunhas dignas de fé, que os ditos Tabelliães conhecam, que digam que as conhecem. E no fim da Nota, os Tabelliães façam menção, como as ditas testemunhas conhecem a parte, ou partes, as quaes assi mesmo assinarão na Nota.` },
        { id: 'of1-tlxxviii-7', number: '7', text: `E farão todos os testamentos, cedulas, codicillos, e quaesquer outras ultimas vontades, e todos os inventarios, que os herdeiros e Testamenteiros dos defuntos e outras pessoas lhes quizerem mandar fazer, per qualquer maneira que seja: salvo os inventarios dos Menores, Orfãos, Prodigos, ou Desasisados, onde houver Scrivão de Orfãos, porque então os fará elle; e onde não houver o tal Scrivão, os farão os Tabelliães do Judicial. E postoque os inventarios hajam de ser feitos entre Maiores e Menores, Prodigos e Desasisados, mandamos que sempre o Scrivão dos Orfãos os faça. Nem farão assi mesmo os inventarios, que os Juizes de seu Officio mandarem fazer, de bens de pessoas absentes, ou que morrerem sem herdeiros: porque os taes inven- [INCERTO: texto continua alem do limite da pagina] A falta de uma escritura no livro de Notas obriga o Tabellião a responder por crime de falsaria, e nem he crido quanto à perda do livro, não provando que houve incendio, naufragio ou outro caso fortunito.

[INCERTO: texto da nota anterior sobre requeridos para fazer] rogo, bem como de duas testemunhas, ao menos. Ord. cit.

8.a Lançamento da escritura em livro de Notas, e nunca em papel avulso ou canhenho. Ord. cit.

9.a A estipulação e aceitação do Tabellião à benefício dos absentes, ou outras pessoas interessadas no contracto. Ord. do liv. 3 t. 63 pr.

No Manual de Corrêa Telles §§ 7 e 8 vem compendiadas as clausulas reprovadas nas escrituras, cuja encorporação importa ou não pena ao Tabellião.

Outrora havia um livro em poder do Regedor da Casa da Supplicação e dos Governadores ou Chancelleres das Relações, em que os Tabelliães dos respectivos districtos ião fazer o seu signal público, do que se passava certidão no verso de suas Cartas. Ord. deste liv. t. 1 § 44 e t. 90 § 1.

tarios devem fazer os Scrivães das audiencias, que perante elles screvem.` },
        { id: 'of1-tlxxviii-8', number: '8', text: `Item, os ditos Tabelliães das Notas farão todos os instrumentos das posses, que forem dadas, ou tomadas per poder e virtude das scripturas das vendas, escaimbos, aforamentos e emprazamentos, e de outros quaesquer contractos, segundo se contém no quarto Livro no Titulo 58: Dos que tomam forçosamente a posse da cousa, que outrem possue. E quanto ás posses, que forem tomadas per vigor de sentenças, ou mandados de Juízes, farão os instrumentos dellas os Tabelliães Judiciaes, como se dirá em seu Titulo 79.` },
        { id: 'of1-tlxxviii-9', number: '9', text: `E screverão os Tabelliães das Notas as receitas e despesas dos bens dos defuntos, que seus Testamenteiros recebem e despendem per vigor dos testamentos. E isto, quando os ditos defuntos em seus testamentos não ordenaram Scrivães certos para screver as ditas receitas e despesas; porque sendo per elles ordenados, esses Scrivães screverão as ditas receitas e despesas. Porém os Tabelliães das Notas farão as Cartas das vendas e rematações dos ditos bens.` },
        { id: 'of1-tlxxviii-10', number: '10', text: `Outrosi, farão quaesquer Cartas de vendas, compras, escaimbos, arrendamentos, aforamentos, ou soldadas, que se fizerem dos Orfãos e de seus bens, quando passarem de tres annos, ou os preços dos ditos arrendamentos, ou soldadas passarem de sessenta mil réis. Porque os arrendamentos até tres annos, e que não passarem de sessenta mil réis, ha de fazer o Scrivão dos Orfãos, como se contém em seu Titulo 89.` },
        { id: 'of1-tlxxviii-11', number: '11', text: `E assi farão os ditos Tabelliães quaesquer obrigações e contractos, que algumas pessoas fizerem, sendo presas, postoque taes scripturas se hajam de fazer per mandado, auctoridade e em presença dos Juizes.` },
        { id: 'of1-tlxxviii-12', number: '12', text: `Farão outrosi os instrumentos de emprazamentos, obrigações, arrendamentos, algueres de casas, e quaesquer outros contractos e convenças, que se fizerem entre partes, postoque as ditas scripturas de consentimento das partes, por maior firmeza, se hajam de julgar per sentença de alguns Julgadores.` },
        { id: 'of1-tlxxviii-13', number: '13', text: `E mandamos aos Tabelliães das Notas, que não façam contractos, nem convenças, em que as partes se obriguem per juramento ou boa fé, cumprir e manter os ditos contractos, sob pena de haverem as penas, que se contém no Livro quarto, Titulo 73: Que se não façam contractos, nem distractos com juramento, etc.` },
        { id: 'of1-tlxxviii-14', number: '14', text: `E não farão Carta alguma de venda, nem outro contracto de bens de raiz, nem de cousa alguma de que se deva Sisa, sem primeiro as partes lhes presentarem certidão do Juiz do lugar, em que os taes bens de raiz stiveram, em que se declare, como pagaram a Sisa, e fica entregue ao Recebedor. Na qual certidão serão declarados os nomes dos contrahentes, e dos bens, que se vendem, e do preço, e em que parte stão, e o nome do Recebedor, e será feita pelo Scrivão das Sisas do tal lugar, e assinada per elle e pelo Juiz e Recebedor, e será incorporada de verbo ad verbum nos ditos contractos. E Contra esta disposição, reproduzida de legislação anterior, oppôz-se em Portugal o Estado Ecclesiastico por differentes vezes, mas sem fructo, pela obstinação dos Reys e seus Ministros, a pretexto de não ser prejudicada a jurisdicção Real, como se pôde vêr da segunda Concordata do Rey D. João I art. 44 a pags. 146 e 147 notas e (*) no nosso Direito Civil Ecclesiastico Brasileiro t. 1.

Hoje que a secularisação do Estado acabou quasi que inteiramente com a jurisdicção da Igreja, esta legislação não tem presentemente significação, ou razão de ser.

Barbosa, Pereira de Castro e Pegas dão á palavra Sisa uma curiosa etymologia. Dizem que a Rainha D. Felippa, esposa de D. João I, e que era Ingleza, da família Lancaster, applaudindo a creação ou continuação do imposto, se expressára á modo de seus patricios, dizendo em vez de imposto de bom siso ou ajuizado, imposto ou direito de boa sisa, resultando chamar-se de então para cá Sisa, e não gabella.

Segundo Cabedo 2ª p. dec. 113, e Duarte Nunes de Leão (Chronica de D. João I) esse imposto, que era outrora lançado pelas Camaras para necessidades dos respectivos Municípios, foi solicitado por aquelle Principe aos Povos tão sómente por um triennio; e de triennio em triennio ficárão os Reys de posse delle, de modo que tornou-se um imposto permanente e ordinario.

Pagão aquelle imposto:

o Tabellião, que o assi não cumprir, perderá o Officio; e as scripturas que se fizerem contra fórma desta Ordenação, serão nullas e de nenhum effeito. E as proprias partes, ou seus herdeiros poderão annullar os ditos contractos, em qualquer tempo que quizerem, e cobrar as novidates das ditas propriedades, desdo tempo que assi contractaram. E não escusará aos Tabellias da dita pena presentar as proprias certidões de como fica paga a Sisa, se não forem trasladadas nas scripturas. E isto mesmo se guardará nos bens, Pagão sómente meia sisa:

Não pagão este imposto:

que se venderem em pregão; nos quaes os Scrivães que fizerem as rematações, serão obrigados do dia da rematação a tres dias, o fazerem screver no Livro das Sisas, e cobrar certidão do Scrivão dellas de como ficam assentadas. E o mesmo se guardará nas vendas e trocas, que se fizerem de Nãos, Navios, Barcas e Batelps. E na cidade de Lisboa se apresentará certidão do Scrivão das Sisas do ramo, a que pertencer, assinada per elle e pelo Almoxarife da Casa.` },
        { id: 'of1-tlxxviii-15', number: '15', text: `E o Tabellião das Notas, que fizer instrumento de approvação em testamento, sem ser assinado pelo Testador e testemunhas, perderá o Officio. E no fazer dos testamentos terão a fórma, que diremos no Livro quarto, no Titulo 80: Dos testamentos, e em que fórma se farão, sob as penas e clausulas nelle conteúdas.` },
        { id: 'of1-tlxxviii-16', number: '16', text: `E não farão contracto algum, de qualquer qualidade que seja, ou convença, em que intervenha dar, ou tomar dinheiro per moedas antigas, senão pelas moedas de ouro, prata, ou cobre, que no Reino correrem ao tempo do tal contracto, sob pena de perdimento dos Officios.` },
        { id: 'of1-tlxxviii-17', number: '17', text: `E darão as scripturas, que houverem de fazer, a seus donos, do dia que as notarem, a tres dias, e se elles lhas pedirem. E sendo as scripturas grandes Convem notar que os traslados podem ser escritos por outras pessoas, e subscritos pelo Tabellião, segundo diz Pegas no respectivo Com.

(porque as não podem em tão pouco tempo dar), dar-lhas-hão do dia que as pedirem, a oito dias. E não lhas dando no dito tempo, serão obrigados pagar à parte as perdas, danos e interesses, que pelo retardamento se lhe causarem. E mais lhe darão a scriptura de graça.` },
        { id: 'of1-tlxxviii-18', number: '18', text: `E fazendo algumas scripturas, que pertençam e devam ser dadas a ambas as partes, se huma dellas pedir cada huma scriptura, seja-lhe dada, ainda que a outra parte não peça a sua.` },
        { id: 'of1-tlxxviii-19', number: '19', text: `E em todos os contractos de obrigações, aforamentos, arrendamentos, compras, vendas, apenhamentos, e quaesquer outros semelhantes, em que alguma parte se obrigue a outra fazer, ou dar alguma cousa depois que o Tabellião huma vez der instrumento pela Nota à parte, a que pertencer, não lhe dará mais outro por nenhuma causa, nem razão, que lhe allegue, salvo havendo para isso nossa Carta. A qual lhe mandarão dar os Desembargadores do Paço, presentes as partes, e com salva na fórma costumada. E fazendo o contrario, perderão os Officios, e mais haverão qualquer outra pena conteúda em nossas Ordenações.` },
        { id: 'of1-tlxxviii-20', number: '20', text: `E em cada Aldea que tiver vinte visinhos, e stiver afastada da cidade, ou villa huma legoa, haja huma pessoa apta para fazer os testamentos aos moradores da dita Aldea, que stiverem doentes em cama. E sendo feitos segundo fórma de nossas Ordenações, ser-lhes-ha dada a fé e auctoridade, como que foram feitos per Tabellião das Notas. E os Officiaes da Camera poderão escolher a tal pessoa morador na dita Aldea, e servirá o dito Officio em sua vida, e dar-lhe-hão juramento scripto no livro da Camera, ao pé do qual deixará feito seu sinal público. E será obrigado ter hum quaderno bem cosido, em que screva os ditos testamentos, quando lhos mandarem fazer nas Notas. E commettendo nelles qualquer erro, incorrerá nas penas, em que incorrera o Tabellião público, que o tal erro ou falsidade commetter. E não tolhemos, que os moradores dessa Aldea possam fazer os testamentos, postoque doentes stêm, com os Tabelliães da cidade, ou villa, ou como quizerem, segundo fórma de nossas Ordenações.

Salarios.` },
        { id: 'of1-tlxxviii-21', number: '21', text: `E levarão da scriptura, que fizerem das Notas em papel, se for tal, que encha huma meia folha scripta de ambas as bandas, quarenta e quatro réis, e de sua nota trinta e sete réis. E se for scripta de huma só banda, levarão vinte e dous réis, e da Nota dezanove réis, e dahi para baixo a este respeito: com tanto que em cada pagina haja vinte cinco regras, e em cada regra trinta letras, pouco mais, ou menos: de modo que contando as letras de sete, ou oito regras, fiquem humas por outras de trinta letras. E não tendo a dita pagina tantas regras, como dito he, não lhe contarão as ditas paginas, senão às regras, a cinco regras por dous réis. E não sendo as regras de tantas letras, não lhe contarão dellas cousa alguma. E se forem fóra da casa deputada, a fazer a tal scriptura, levarão mais sete réis da ida; e quando acabarem de screver as scripturas nas Notas, levarão o que nas ditas Notas se montar. E quando entregarem à parte as scripturas, que das Notas tirarem, então lhe pagarão o que se montar nellas.` },
        { id: 'of1-tlxxviii-22', number: '22', text: `E se fizerem scripturas outras, assi como inventarios, ou outros autos semelhantes, sejam-lhes contados às regras, assi como levam os outros Tabelliães dos processos.

Esse Decreto se encontra nos Additamentos à este liv., com as respectivas alterações.

Confronte-se com a Ord. deste liv. t. 70 §§ 6 e 27, e t. 80 § 15.` },
        { id: 'of1-tlxxviii-23', number: '23', text: `Item, quando buscarem alguma Nota per seus livros, ou instrumentos, que das Notas tenham tirados, e não forem requeridos pelas partes, a que pertencia, de maneira que não steve pelo Tabellião, levarão sómente de busca ametade do que he ordenado de se levar de busca dos processos e outras scripturas, como se dirá no Titulo 84: Do que hão de levar os Tabelliães e Scrivães.` },
        { id: 'of1-tlxxviii-24', number: '24', text: `E o Tabellião, que não cumprir todo o conteúdo neste Regimento, e no Titulo 80: Das cousas que são communs aos Tabelliães das Notas e aos do Judicial, perderá o Officio, e pagará o dano e perda às partes: salvo nos casos, em que logo he posta certa pena, porque nesses haverá a dita pena nelles declarada.` },
      ],
    },
    {
      id: 'titulo-lxxix',
      title: `LXXIX. Dos Tabelliães do Judicial`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxix-preambulo', number: 'Preâmbulo', text: `Mandamos, que nas cidades e villas de nossos Reinos, onde stiverem per Nós Juizes de fóra, sempre em sua casa sté hum Tabellião de Judicial tres horas pela manhã e tres à tarde, que começerão ao tempo, que pelo Juiz for ordenado, cada hum sua semana, ou per distribuição, como se elles concertarem.` },
        { id: 'of1-tlxxix-1', number: '1', text: `E tanto que o Juiz começar de servir, logo nesse mez lhe dêm as querelas, que tiverem, e lhe mostrem as inquirições, em que tiverem alguns culpados. E assi o façam dahi em diante em cada hum mez, sob pena de privação dos Officios. E para certeza de como lhas mostram, farão hum rol dellas, do qual ficará hum traslado na mão do Juiz, e outro assinado per elle na mão do Tabellião. E isto haverá outrosi lugar nos Scrivães dante alguns Julgadores, que tiverem querelas, ou inquirições, em que haja algumas pessoas culpadas.` },
        { id: 'of1-tlxxix-2', number: '2', text: `E serão obrigados os ditos Tabelliães dar todas as culpas ao Corregedor da Comarca do dia, que chegar ao lugar, a tres dias. E não lhas dando, ou sonegando algumas, serão privados dos Officios, como mais largamente dissemos no Titulo 58: Dos Corregedores das Comarcas.` },
        { id: 'of1-tlxxix-3', number: '3', text: `E terão cuidado de notificar aos Juizes, quando tiverem alguma querela, que passar de hum anno, sem per ellase fazer obra, para que proceda contra os querelados. A qual notificação assinará o Juiz ao pé da querela, sob pena de perderem os Officios.` },
        { id: 'of1-tlxxix-4', number: '4', text: `E quando todos os Tabelliães do Judicial de hum lugar forem suspeitos em alguma causa, então hum Tabellião das Notas screverá nella. E sendo suspeito, screverá o Scrivão da Camera. E sendo elle outrosi suspeito, então virá hum Tabellião do mais chegado lugar, e screverá na dita causa.` },
        { id: 'of1-tlxxix-5', number: '5', text: `Os Tabelliães serão mui prestes e diligentes, assi para nas audiencias, em que são ordenados, screverem todos os autos, que perante os Juizes passarem, e todos os que a bem de justiça pertence fazer, e screverem o que a seus Officios toca, e o que lhes for mandado pelos Juizes, ou requerido pelas partes, em maneira que por sua negligencia a justiça não pereça, nem as partes percam seu direito. E para isto irão cedo as audiencias, de maneira que elles aguardem pelos Juizes, e não os Juizes por elles.` },
        { id: 'of1-tlxxix-6', number: '6', text: `E serão obrigados continuar todos os feitos no dia, que forem offerecidos, e os elles receberem nas audiencias. E no dito dia, ou a mais tardar no outro, os dêm aos Juizes, ou Procuradores, a que houverem de ir. Porém, se nos ditos feitos forem offerecidas tantas e taes scripturas, que tão em breve se não possam trasladar, o Julgador lhes assine termo conveniente, em que as possam trasladar. E tanto que forem trasladadas, as concertarão com outro Tabelliào, que lhes porá o concerto ao pé, e assinará de seu sinal. E não as concertando na dita fórma, pagará ás partes toda a perda, dano e custas, que por ello receberem, ou se causarem. E não dando os feitos, ou não fazendo as ditas Cartas no dito termo, pagarão dez cruzados, ametade para a parte, e a outra para Captivos: e desta dos Captivos haverá quem o accusar ametade, ainda que seja a propria parte. E não mandando os feitos aos Juizes, ou Procuradores nos termos em que se devem dar, pagarão ás partes, além da pena acima dita, as custas do retardamento; as quaes o Contador lhes descontará de seus salarios. E para não vir em duvida, quando deram os feitos, porão sempre nelles o dia, em que os deram ao Juiz e Procuradores.` },
        { id: 'of1-tlxxix-7', number: '7', text: `E porão na continuação dos termos e no princípio do feito e nas sentenças e Cartas, que passarem, o nome do Julgador e do Officio sómente, per que conhece do dito feito. E não lhe porão outros nomes, nem dignidades, postoque as tenha. E o Tabelliào, ou qualquer outro Scrivão, que o contrário fizer, pagará dous mil réis para quem o accusar, e Captivos.` },
        { id: 'of1-tlxxix-8', number: '8', text: `Outrosi as Cartas que per algum desembargo houverem de fazer, as fação logo em esse dia, ou até o outro pela manhã, se nelle as não podérem fazer. Porém se o Juiz, cujo o desembargo for, vir que se não podem fazer no dito tempo, assine-lhes termo, em que as possam fazer, e sem malicia.` },
        { id: 'of1-tlxxix-9', number: '9', text: `E serão muito prestes para irem com os Juizes, ou per seu mandado fazer quaesquer autos, que pertencerem a bem de Justiça, e a tirar quaesquer inquirições, que pelos Juizes lhes for mandado, assi devassas, como judiciaes, geraes e speciaes, em todos os maleficios, assi por parte da Justiça, como a requerimento das partes danificadas; as quaes inquirições devassas lhes serão pagas, segundo dissemos no Título 65: Dos Juizes ordinarios.` },
        { id: 'of1-tlxxix-10', number: '10', text: `E as scripturas, que se fazem com traslado de outras em pública fórma per auctoridaде dos Juizes; e as das appellações que algumas partes intimam dante quaesquer Juizes Ecclesiasticos, ou seculares, ou Cartas de vendas, ou arrematações, que se fizerem per virtude de algumas sentenças, façam-as os Tabelliães das audiencias, que péraote os Juizes screvem.` },
        { id: 'of1-tlxxix-11', number: '11', text: `E todos os Tabelliães e Scrivães, quando tirarem inquirições judiciaes, sempre perguntem as testemunhas no começo de seus ditos e testemunhos polo costume e idade. E nas devassas geraes e spe- ciaes pergunjem polo costume no fim de cada testemunho, sob pena de perderem os Officios, e nunca os mais haverem.` },
        { id: 'of1-tlxxix-12', number: '12', text: `E quando tirarem testemunhas, e algumas disserem, Nihil, o screverão na fórma que diremos no Titulo 86: Dos Enqueredores.` },
        { id: 'of1-tlxxix-13', number: '13', text: `E farão os inventarios, que os Juizes de seu Officio mandarem fazer dos bens de pessoas absentes, ou que fallecerem sem herdeiros. Os quaes inventarios os Juizes mandarão fazer de seu Officio, postoque lhes não seja requerido per alguma parte. E assi farão os inventarios dos Menores, Orfãos, Prodigos, Desasisados, onde Scrivão dos Orfãos não houver.` },
        { id: 'of1-tlxxix-14', number: '14', text: `E serão muito diligentes em irem fazer as execuções, e tomar as possives de bens de raiz, penhoras, arrematações e entregas, e todos os outros autos, quando pelos Juizes forem mandados. De maneira que por sua culpa e negligencia não sejam retardadas as ditas execuções. E de todos os ditos autos farão e passarão as scripturas e instrumentos, que lhes forem requeridos pelas partes.` },
        { id: 'of1-tlxxix-15', number: '15', text: `Item, screverão de graça os autos e emprazamentos, e scripturas, que lhes pelos Alcaides Móres das Sacas for requerido, sob pena de perdimento dos Officios; e o mesmo farão nas diligencias da nossa Fazenda, como fica dito no Titulo 24: Dos Scrivães dante os Desembargadores do Paço.` },
        { id: 'of1-tlxxix-16', number: '16', text: `Item, nenhum Tabellião tomará dinheiro, nem outra cousa alguma á conta de seu salario, antes de lhe ser contado, Tambem se chamou depois emprazamento o contracto da emphyteusis, pelo qual o senhor do predio dá parte delle á quem o cultiva, transferindo-lhe o dominio util, e recebendo certa pensão annual. Havia annuaes, por uma vida, por tres, e perpetuos.

Estas disposições facultão ao Tabellião ou Escrivão da parte, que perante elle trouxer feito, postoque diga que lho descontou, ou descontará do salario, sob pena de perdimento do Officio, para nunca mais o haver.` },
        { id: 'of1-tlxxix-17', number: '17', text: `E tanto que o feito for findo, postoque não seja requerido per nenhuma das partes mandarão dahi a hum mez o dito feito ao Contador, e o farão contar, sob as penas, que dissemos no Titulo 24: Dos Scrivães dante os Desembargadores do Paço. E elles em nenhuma maneira contarão o feito em que houverem de haver salario, sob pena de privação dos Officios.` },
        { id: 'of1-tlxxix-18', number: '18', text: `E demandarão seus salarios do dia, que as sentenças diffinitivas forem dadas nos feitos, a tres mezes. E não os demandando no dito tempo, não os poderão mais demandar.` },
        { id: 'of1-tlxxix-19', number: '19', text: `E todo o Tabellião e Scrivão, que não for da Corte, nem das Sisas, poderá em cada hum anno ir fóra do lugar, onde for Tabellião ou Scrivão, sem licença do Julgador, perante quem screver, oito dias sómente. E indo fóra do dito lugar sem sua licença, e andando mais dos oito dias em cada hum anno, será suspenso do Officio per hum anno, e pagará ás partes toda a perda e dano, que por sua ida e absencia se lhes causar. A qual licença lhe poderá o Julgador, perante quem screver, dar, a todo mais, até tres mezes cada anno sómente, se para tanto tempo vir que o dito Official tem necessidade. E andando fóra mais que os ditos tres mezes (postoque seja com licença do Julgador), será privado do Officio. E quando lhe assi der a dita licença, ficará seu carrego a outro Scrivão, ou Tabellião do mesmo Officio, ou auditorio, a quem o elle deixar. E lhe a cobrança executiva dos seus salarios, sendo contados.

Mas qual será a sentença definitiva? A da 1ª instancia, a ultima da Relação, ou a da Relação Revisora?

Eis o que não está definido.

dará informação dos feitos e autos que deixar, em modo que não sejam as partes por essa razão detidas, sob pena de pagar as custas e perdas ás partes, que por o assi não deixar, se lhes causar. E não havendo hi outro Official de seu Officio, a que seu carrego haja de ficar, o Julgador lhe não dará licença, e dando-lha, será nenhuma. E quanto aos Scrivães da Corte e das Sisas, guardar-se-ha o que per nossas Ordenações he determinado.

Distribuição.` },
        { id: 'of1-tlxxix-20', number: '20', text: `E onde houver dous Tabelliães do Judicial, ou mais, haverá hum Distribuidor. E nenhum seja ousado de screver, nem fazer Carta, ou qualquer outra scriptura, senão a que lhe for per o dito Distribuidor distribuída. E o que fizer o contrario pagará ás partes as custas, e mais pagará pola primeira vez duzentos réis para a Piedade; e pola segunda será suspenso, per seis mezes; e pola terceira privado do Officio. Porém poderão screver sem distribuição, quando pelo Juiz do feito lhes for mandado, e tiver necessidade de o mandar fazer, sem se distribuir, ou por ahi não starem os outros Tabelliães, ou o Distribuidor, ou por não haver tempo para se distribuir. E o dito Tabellião dentro em tres dias será obrigado de o dizer ao Distribuidor, para lho carregar na distribuição. E não lho dizendo, haverá a pena que haveria, se o fizera sem mandado do Juiz. E mandamos que nenhum Tabellião possa ter, nem servir o Officio de Distribuidor, nem Contador, nem Enqueredor, sob pena de perdimento dos ditos Officios, e dos que assi tiver, ou servir.` },
        { id: 'of1-tlxxix-21', number: '21', text: `E quando se achar, que os feitos e autos não são distribuídos, os Julgadores, que delles conhecerem, os farão distribuir, em quaesquer termos que stiverem, sem por isso se annullarem.

Appellações.` },
        { id: 'of1-tlxxix-22', number: '22', text: `Quando as demandas forem sobre bens de raiz, o Tabellião ou Scrivão que a appellação houver de fazer, ou o feito de aggravo houver de mandar, se das sentenças, que os Juizes das appellações derem for aggravado, não as cerrará, nem entregará ao appellante, nem aggravante, sem primeiro serem postas na dita appellação e feito de aggravo as procurações das molheres dos litigantes, se casados forem, para proseguimento das appellações, ou feitos de aggravo. E se alguma das partes appellantes, ou aggravantes não quizer trazer procuração de sua molher, o Juiz do feito lhe não assinará termo para seguir appellação, ou aggravo; antes passado o tempo, que pela Ordenação para isso he limitado aos appellantes, ou aggravantes, elles não poderão mais seguir suas appellações, ou aggravos. E quanto ás partes appelladas, ou aggravadas, não serão obrigadas trazer procurações de suas molheres; mas os Juizes, que a appellação ou aggravo houverem de atempar, mandarão aos appellantes, ou aggravantes, que citem as molheres dos appellados, ou aggravados, quando citarem os maridos. E o Tabellião ou Scrivão, que o feito da appellação ou aggravo entregar sem as ditas procurações, ou citações, incorrerá em pena de perdimento do Officio. Porém, se a molher, cuja procuração, ou citação se requere para o caso da appellação, ou aggravo, tiver dado procuração bastante a seu marido para seguir a dita appellação, ou aggravo, e a tal procuração stiver já offerecida no feito, não será necessaria outra procuração, nem citação da dita molher.` },
        { id: 'of1-tlxxix-23', number: '23', text: `E quando mandarem alguma appellação sobre bens de raiz, porão nella e nos dias de apparecer a avaliação dos ditos bens, como se contém no Livro terceiro, no Título 84: Dos aggravos das sentenças difinitivas, sob as penas ahi postas.` },
        { id: 'of1-tlxxix-24', number: '24', text: `E assi porão no fim das appellações, antes que as mandem, o traslado da conta, que o Contador fez, do que montou haver ao Tabellião, assi do proprio feito como do traslado. E mandando as appellações sem a dita conta, serão privados dos Officios.` },
        { id: 'of1-tlxxix-25', number: '25', text: `E porque trasladar nas appellações a leitura, que se screve nas suspeições, he desnecessário, nenhum Tabellião, nem Scrivão traslado nas appellações as suspeições, nem os termos dellas, nem os testemuuhos, que sobre ellas forem tirados; sómente farão hum termo, como foi posta suspeição ao Julgador, ou ao Official, e foi julgado por suspeito, ou por não suspeito, e foi a outro, como consta dos autos da suspeição, que em seu poder ficam: salvo se per alguma das partes lhe for requerido, que traslade o que dito he das suspeições, porque então o trasladará. E antes que cerre a appellação, fará assinar a parte no mesmo traslado da appellação, que ao superior ha de ir, como he verdade que lho requereo, e a mesma parte, que lho requereo, pagará o traslado e a vista, que se nelle montar na causa da appellação, assi da sua parte, como da parte contraria. E postooque a parte, que o assi requereo, seja vencedor nas custas, não lhe serão contadas as que se fizerem no tal traslado, nem o que pagou da vista na causa da appellação. E o Scrivão, ou Tabellião, que o assi não cumprir, pagará à parte, que o accusar, tudo o que se montar no traslado da dita appellação.` },
        { id: 'of1-tlxxix-26', number: '26', text: `E bem assi mandamos sob a dita pena, que no traslado das appellações não trasladem Carta alguma, per que se tirasse inquirição per artigos, que no feito stão, donde saíram as ditas Cartas: salvo se per alguma das partes lhes for requerido; porque então se cumprirá em todo o que acima dito he nos autos das suspeições.` },
        { id: 'of1-tlxxix-27', number: '27', text: `E quando quer que houverem de dar às partes algumas appellações, primeiro as concertem perante ellas de maneira, que não possam dizer onde taes appellações, ou traslados de scripturas forem vistas, que são diminutas, ou accrescentadas. E para se isto evitar, farão assinar às partes o concerto, quando fôrem presentes, ou ao outro Tabellião, sob pena de privação dos Officios, e de lhes pagarem as perdas, danos e custas, que se lhes por isso causarem.` },
        { id: 'of1-tlxxix-28', number: '28', text: `E pelo dito modo farão concertar todos os autos, que derem em publica fórma: e assi as Cartas, que fizerem, para se tirarem inquirições per artigos. E não as concertando, haverão as penas acima ditas. As quaes outrosi haverá o Tabellião, que concertar a scriptura alhea, que se não achar ser na verdade.

Feitos crimes.` },
        { id: 'of1-tlxxix-29', number: '29', text: `E faça cada hum Tabellião seu livro encadernado de cadernos iguaes, de tantas folhas hum como outro, e de papel de huma marca e grandeza, para nelles screverem as querelas obrigatorias, que pelos Juízes e Justiças forem recebidas aos querelosos nos casos, em que per nossas Ordenações o devem ser. O qual livro será assinado e numerado pelo Juiz da terra, sabendo ler e screver, e não sabendo, o será pelo seu Superior. E o Tabellião, que o contrario fizer, e for comprendido em malícia, ou negligencia, perderá o Officio.` },
        { id: 'of1-tlxxix-30', number: '30', text: `E serão avisados de não por, nem screver, nem deixar de screver mais palavras, ou menos, das que lhes forem ditas pelos querelosos. As quaes depois de terem scriptas, lhes lerão todas de verbo ad verbum perante o Juiz, que a querela receber. E depois de lida assi a querela, será assinada pelo quereloso e pelo Juiz. E o Tabellião, que o contrario fizer, perca logo o Officio, e seja preso, para lhe mandarmos dar a pena de falso, ou outra, qual houvermos por bem.` },
        { id: 'of1-tlxxix-31', number: '31', text: `Outrosi mandamos a todos os Scrivães das audiencias, assi da Corte, como da Casa do Porto, e a quaesquer outros, que em feitos crimes houverem de screver, que quando duas, ou mais pessoas forem presas, ou demandadas juntamente por um crime ou caso, ou se quizerem livrar delle per Carta de seguro, ou per outra maneira alguma, não façam senão hum feito, em que todos juntamente sejam ouvidos; salvo se alguma das partes requerer ao Julgador, que faça sobre si feito apartado. E o Tabellião, ou Scrivão que o contrario fizer, incorrerá por cada vez em pena de dous mil réis para a Mizericordia. Porém não tolhemos que cada parte possa tirar sua sentença de seu livramento para ter em seu poder.` },
        { id: 'of1-tlxxix-32', number: '32', text: `Item, o Tabellião será obrigado sob pena de perder o Officio, tanto que algum feito de pessoa, que se livra com Carta de seguro, ou Alvará de fiança, de que for Scrivão, stiver quinze dias sem se fallar a elle, de o notificar ao Julgador; como se contém no livro quinto, no Titulo 124: Da ordem do Juizo nos feitos crimes.` },
        { id: 'of1-tlxxix-33', number: '33', text: `E o Tabellião não dará mais testemunhas no feito, em que for Promotor, que as da querela, ou devassa, ou as nella referidas; salvo da maneira, que diremos no Livro quinto, no Titulo 124: Da ordem do Juizo nos feitos crimes, e sob a pena hi conteuda.` },
        { id: 'of1-tlxxix-34', number: '34', text: `E os Tabelliães, que fôrem presentes á prisão de quaesquer homens, hão de screver o habito e tonsura, em que forem achados, sob as penas declaradas no Livro quinto, no Titulo 121: Que ao tempo da prisão se faça auto, etc..` },
        { id: 'of1-tlxxix-35', number: '35', text: `E nos feitos de presos porão o auto da prisão, sob pena de privação dos Officios, como se contém no Livro quinto, Titulo 124: Da ordem do Juizo nos feitos crimes.` },
        { id: 'of1-tlxxix-36', number: '36', text: `E o que sonegar as culpas na folha, haverá a pena, que se contém no Livro quinto, Titulo 125: Como se correrá a folha.` },
        { id: 'of1-tlxxix-37', number: '37', text: `E hão de pôr em stado, quando os Julgadores não procederem contra os que levantaram volta em Juizo, como se contém no Livro quinto, Titulo 51: Do que alevanta volta em Juizo.` },
        { id: 'of1-tlxxix-38', number: '38', text: `E quando vir que o Alcaide faz avença com alguma pessoa sobre lhe deixar trazer armas defesas, ou que dá licença, ou consente que as tragam, sem as coutar e accusar, o porá em stado, e o dará ao Juiz, sob pena de privação do Officio, como he conteúdo no Titulo 75: Dos Alcaides pequenos, § 23.` },
        { id: 'of1-tlxxix-39', number: '39', text: `E serão obrigados, cada vez que forem requeridos per bem de justiça para ir aos lugares do Concelho onde assi forem Tabelliães, a fazer quaesquer autos, ou scripturas, que per razão de seus Officios são obrigados fazer, de irem logo com muita diligencia, sem levarem dinheiro algum da ida: sómente levarão o que lhes directamente montar nas scripturas e autos, que fizerem.` },
        { id: 'of1-tlxxix-40', number: '40', text: `E defendemos a todos os ditos Tabelliães, que não recebam tença, nem acostamento de alguns Fidalgos, nem se acostem a elles, nem recebam delles quita das pensões, que devam haver dos Tabelliães; per doações que de Nós tenham. E o Tabellião, que o contrario fizer, por esse mesmo caso perca o Officio, e Nós o poderemos dar, a quem nossa mercê fôr.` },
        { id: 'of1-tlxxix-41', number: '41', text: `Outrosi defendemos, que pessoa alguma, que for criado de Alcaide Mór de alguma cidade, villa, ou lugar, ou de algum Fidalgo, não haja Officio de Tabellião do Judicial, nem o sirva por outrem no lugar, onde o dito seu senhor for Alcaide Mór, ou o dito Fidalgo viver. E havendo o dito Officio, seja privado delle, para o darmos a quem for nossa mercê. E servindo por outrem, perderá a stimação do dito Officio, ametade para quem o accusar, e a outra para os Captivos.` },
        { id: 'of1-tlxxix-42', number: '42', text: `E o Tabellião que não dér ao Chanceller da Comarca no dia, em que per elle lhe for requerido, em rol todas as penas, em que algumas pessoas incorreram para a Chancellaria, será suspenso do Officio até nossa mercê, e mais pagará as ditas penas.` },
        { id: 'of1-tlxxix-43', number: '43', text: `Item, hão de assentar no auto da penhora, que fizerem, como a parte foi requerida, sob pena de perderem os Officios, como se contém no Livro terceiro, Titulo 86: Das execuções, no principio.` },
        { id: 'of1-tlxxix-44', number: '44', text: `E hão de pôr na publicação das sentenças, se foram as partes presentes ao publicar dellas, sob pena de perderem os Officios.

Parentescos.` },
        { id: 'of1-tlxxix-45', number: '45', text: `E por se evitarem os inconvenientes, que por causa do parentesco dos Tabelliães do Judicial se poderiam seguir, se pai e filho, ou outros parentes muito chegados e cunhados fossem em hum lugar Tabelliães, mandamos que em nenhuma cidade, villa, ou Concelho, sejam juntamente em hum tempo pai e filho Tabelliães do Judicial, nem dous irmãos, nem primos comirmãos, nem thio e sobrinho, filho de irmão, ou irmã, nem cunhados` },
        { id: 'of1-tlxxix-46', number: '46', text: `E além dos casos conteúdos neste Titulo, serão obrigados cumprir o que lhes he mandado per nossas Ordenações, Regimentos e Direitos, sob as penas nelles declaradas. E assi cumprirão os mandados de seus Superiores, que lhes mandarem por bem de justiça. E não fazendo assi os ditos Superiores os poderão suspender, sem appelação, nem aggravo, não passando de seis mezes. O que outrosi se entenderá em todos os mais Scrivães.` },
      ],
    },
    {
      id: 'titulo-lxxx',
      title: `LXXX. Das causas, que são comuns aos Tabelliães das Notas e aos do Judicial`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxx-preambulo', number: 'Preâmbulo', text: `Os Tabelliães das Notas e os do Judicial serão obrigados ao tempo, que levarem as Cartas de seus Officios, levar de nossa Chancellaria o Regimento de cada hum de seu Officio, e este, que nesta Ordenação lhes damos. E os que forem das Notas e do Judicial juntamente, levarão ambos os Regimentos; os quaes sempre terão, para os poderem mostrar quando lhes for requerido. E o esquecimento não forão contemplados na enumeração que faz a Ordenação.

que não levar os ditos Regimentos, por esse mesmo feito perça o Officio, e nunca mais o haja, nem outro de Justiça. E pagará da cadea vinte cruzados, ametado para os Captivos, e a outra para quem o accusar.` },
        { id: 'of1-tlxxx-1', number: '1', text: `E quando levarem as Cartas dos Officios, levarão nas costas dellas, per assinado e fé do Scrivão da Chancellaria, como nella tomaram juramento, sob pena de perdimento dos Officios. E assi levarão nas costas das Cartas certidão do Regedor, ou Governador da Relação, de cujo districto for o Officio, como fizeram hum termo de sua letra, e hum sinal publico, de que hão de usar no livro da dita Relação, que para isso nella stá ordenado. E sem a dita certidão, as Justiças lhes não darão posses dos Officios.` },
        { id: 'of1-tlxxx-2', number: '2', text: `E antes de começarem a servir, darão fiança scripta per Tabellião publico no livro das Notas, trasladada no livro da Camera, a todo o dano e perda, que a alguma parte se causar por sua malicia, ou culpa. A qual fiança será de trinta mil réis nas cidades, e vinte mil réis nas villas, e nos Concelhos de terras chãs dez mil réis; e servindo sem darem as ditas fianças, perderão os Officios.` },
        { id: 'of1-tlxxx-3', number: '3', text: `E serão obrigados viver e morar continuadamente na cidade, villa, lugar, ou Concelho, em que assi forem Tabelliães das Notas, ou Judicial, sob pena de perderem os Officios. E não poderão ser Tabelliães em differentes Concelhos, cidades villas, ou lugares; salvo se forem tão pequenos e assi conjunctos, que do lugar, onde o Tabellião morar, ao lugar, em que se fizerem as audiencias, não haja mais que duas legoas. E os Tabelliães do Judicial e Scrivães, que o fôrem em differentes Concelhos, irão a todas as audiencias, que nelles se fizerem, assentando com os Juizes os dias e horas, em que se hão de fazer, para que ao tempo, em que forem servir em hum dos ditos Concelhos, não sejam necessarios em o outro. E quando forem ás audiencias de hum Concelho ao outro, não levarão do caminho dinheiro algum ás partes. E quando forem Tabelliães em hum só Concelho, que tiver mais que hum lugar, morarão em hum delles, qual lhes aprouver, com tanto que não seja afastado do lugar, onde se fazem as audiencias, mais de duas legoas, sob a dita pena.` },
        { id: 'of1-tlxxx-4', number: '4', text: `E serão avisados, que em quanto servirem de Tabelliães das Notas ou do Judicial, não tragam coroa aberta, grande, nem pequena. E fazendo o contrario, por esse mesmo feito, sem mais serem citados, percam os Officios, e nunca mais os hajam.` },
        { id: 'of1-tlxxx-5', number: '5', text: `E não serão Juizes em nenhum tempo, que forem Tabelliães, nem advogarão, nem procurarão em Juizo por pessoa alguma, nem aceitarão procuraçào para per ella sobstabelecerem; salvo por seus feitos, ou dos que viverem continuadamente com elles em suas casas, sob pena de perderem os Officios.` },
        { id: 'of1-tlxxx-6', number: '6', text: `Outrosi mandamos, que façam as scripturas declaradas em seus Regimentos, e não tomem as scripturas, que pertencem a outros Officios. E o que fizer o contrario, seja preso e suspenso até nossa mercê. E pagará ás partes o interesse e dano, que por isso receberem, e as scripturas sejam nullas.` },
        { id: 'of1-tlxxx-7', number: '7', text: `E nas scripturas, que fizerem ponham sempre juntamente o dia, mez e anno do Nascimento de Nosso Senhor JESU CHRISTO, e não separado, como aléqui se fazia, e a cidade, villa, ou lugar e casa, em que as fizerem, e assi os seus nomes delles Tabelliaes, que as fazem.` },
        { id: 'of1-tlxxx-8', number: '8', text: `E todos os Tabelliaes sirvam per si seus Officios, e não ponham nelles outras pessoas, que os sirvam por elles. E o que poser outrem em seu Officio, que por elle sirva, não tendo para isso nossa licença special, por esse mesmo feito perca o Officio, e a pessoa, que por elle servir, perca a stimação, amétade para quem o accusar, e a outra para nossa Camera.

Instrumentos.` },
        { id: 'of1-tlxxx-9', number: '9', text: `E se alguma parte pedir instrumento de aggravo, por se sentir aggravada do Juiz, ou instrumento de qualquer outra protestação dante o Juiz para seu Superior, o Tabelliào das Notas, ou do Judicial ou Escrivão dos Contos, ou de outro qualquer Officio de nossa Fazenda, nos casos, em que cada hum delles o pôde passar, ou Carta testemunhavel dante os Corregedores, Ouvidores, Contadores, ou quaesquer outros Officiaes e Justiças, dizendo que lhe não fazem direito, se o Julgador disser, que lhe seja dado instrumento, ou Carta com sua resposta, será obrigado responder em dous dias primeiros seguintes, contados de momento a momento, em que lhe o requerimento for feito per palavra. E se a parte fizer o requerimento per scripto, contar-se-hão os dous dias do momento, em que lhe for apresentado. E se a parte a que tocar quizer responder, responderá em outro tanto termo. E se o Requerente quizer replicar, e a outra parte treplicar, ou o Juiz, podelohão fazer, em hum dia cada hum, contado pela dita maneira. E o Tabelliào, ou Scrivão, será diligente em apresentar o requerimento ao Juiz na hora, que lhe for dado, e em pedir ao Juiz a resposta, ou á parte, e a treplica, no fim de cada hum dos ditos termos. E não lha dando cada hum dos sobreditos ao dito termo, o Tabelliào, ou Scrivão passará o instrumento, ou Carta á parte, que lho pedir, sem a resposta, replica, ou treplica, que lhe assi não for dada. E desta maneira o faça entre as partes, quando lhe alguma dellas pedir instrumento de requerimento, ou protesto, ou de outro qualquer acto fóra de Juizo, se a outra parte lhe não dér resposta no dito termo de dous dias. Porque he de presumir, que o Juiz, ou a parte, que dilata dar resposta, o faz por alongar a demanda, e tolher ao requerente seu direito.` },
        { id: 'of1-tlxxx-10', number: '10', text: `E farão outrosi os instrumentos de notificações, requerimentos, protestações, que algumas pessoas fazem a outras fóra do Juizo, e de citações, que se fazem per nossas Cartas, ou de nossas Justiças, e de entregas de presos a alguns Juizes ou Alcaides, que se delles dão por entregues, e de mandados e auctoridades de Juizes para alguns presos poderem fazer contractos nas cadeas, ou de certidões, como algumas Cartas nossas, ou Alvarás foram apresentados a alguns Juizes e Officiaes, ou a outras pessoas, ou de fé e certidão, como nossas Cartas, ou de nossas Justiças, ou dos Prelados, ou seus Vigarios foram fixadas nas portas das Igrejas, ou lugares publicos. E todas estas scripturas de semelhante qualidade farão os Tabelliaes Judiciaes, ou de Notas, quaes as partes para isso escolherem.` },
        { id: 'of1-tlxxx-11', number: '11', text: `E o Tabellião, ou Serivão assi da Justiça, como da Fazenda, que logo não der o instrumento, ou Carta à parte, que lho requerer, ao outro dia seguinte, depois de passados os ditos termos, ora seja com resposta do Julgador, ou da parte, ou sem ella, por esse mesmo termo a não quizer dar, por esse mesmo feito perca o Officio, e nunca o mais haja, nem outro algum de Justiça, e seja preso, e da cadea pague vinte cruzados para a parte, se o quizer accusar e pedir. E não os querendo demandar, será ametade para os Captivos e a outra para o accusador; e não havendo accusador, serão todos para os Captivos. O que cumprirão, sem embargo que pelos Desembargadores, que a alguma parte mandarmos, postoque Presidente levem, ou pelos Corregedores, Ouvidores, Juizes, Contadores e todos os outros Officiaes de Justiça, ou Fazenda, a que tocar, ou pelas pessoas, que jurisdição tiverem nos lugares, onde se taes instrumentos requererem, lhes seja defeso, que os não dêm. E postoque os taes Officiaes da Justiça, ou Fazenda tenham alçada no caso, porque todavia os darão sob as ditas penas, declarando como o dito Julgador lho prohibia, e que elles per bem desta Ordenação lho deram. E no caso, que algum instrumento for tirado dante alguns Desembargadores, que com alçada mandamos, o tal instrumento não irá a nenhuma das Relações, mas virá a Nós.` },
        { id: 'of1-tlxxx-12', number: '12', text: `E quando passarem alguns instrumentos às partes, declararão toda a verdade dos antos, que pelas partes, ou pelo Juiz for apontada em seus requerimentos, ou respostas, sob pena de privação dos Officios, como se contém no terceiro Livro no Titulo 74: Da maneira, que se terá, quando Juiz não recebe a appellação.` },
        { id: 'of1-tlxxx-13', number: '13', text: `E se depois que o Tabellião, ou Serivão incorrer em as ditas penas, por denegar o instrumento à parte, fizer mais scriptura, ou outra alguma cousa, que a seu Officio pertença, mandamos, que seja preso, e da cadea pague vinte cruzados, ametade para os Captivos, e a outra para quem o accusar: e mais será degradado dez annos para o Brasil, e as partes o poderão demandar polo que lhes levar polas taes scripturas, e não serão valiosas. E aos Juizes e Officiaes, assi da Justiça, como da nossa Fazenda, defendemos, que com o tal Tabellião, ou Serivão não façam cousa alguma, que a seus Officios per-tença. E o que o contrario fizer, pague dous mil réis, ametade para os Captivos, e a outra para quem o accusar.` },
        { id: 'of1-tlxxx-14', number: '14', text: `E mandamos a todos nossos Corregedores, Juizes e Officiaes de Justiça, e assi aos nossos Contadores, Almoxarifes, Juizes das Sisas e Officiaes de nossa Fazenda, Contadores dos Residuos, Ouvidores nossos e das terras dos Mestrados, e assi de Senhores de terras e Grandes de nossos Reinos e Senhorios, que quando quer que semelhantes requerimentos lhes forem feitos, e pedirem disso instrumentos, dêm sua resposta no tempo aqui declarado, e não a dilatem mais. E se passado o dito termo a não dérem, mandamos, que não impeçam, nem tolham aos ditos Tabelliães, ou Scrivães, que passem os ditos instrumentos, ou Cartas testemunhaveis, e lhos deixem fazer e dar às partes, segundo a seus Officios pertence. E não sómente lhos não impedirão, mas serão obrigados a lhes fazer dar os ditos instrumentos, ou Cartas testemunhaveis nos termos acima conteúdos: sob pena de qualquer, que o contrario fizer, e o tal instrumento, ou Carta impedir, ou lha não fizer dar, como dito he, perder por esse mesmo feito o Officio; e será inhabil para nunca mais ter Officio de Justiça, nem outro algum de cidade, villa, ou lugar, e mais pagará vinte cruzados à parte, se quizer accusar. E não accusando a parte, será ametade para quem o accusar, e a outra para os Captivos. E se mais usar do dito Officio sem Provisão nossa, haverá aquella pena, que haveria a pessoa, que sem nossa auctoridade servisse Officio de Justiça. E se o que tiver a jurisdição da terra, defender dar-se o tal instrumento, seja suspenso della, em quanto o Nós houvermos por bem.` },
        { id: 'of1-tlxxx-15', number: '15', text: `E serão avisados os ditos Tabelliães, que os taes instrumentos fizerem, se os fizerem per petições, que lhes a parte dérem, que tanto que as ditas petições forem per elles trasladadas, sejam lidas e concertadas perante as partes, se a isso quizerem ser presentes. E quando não fôrem presentes, sejam concertadas com outro Tabellião, o qual porá o concerto, e assinará de seu sinal raso. E não lhe pondo o dito concerto, será privado do Officio, e pagará à parte toda a perda, dano e custas, que por isso receber.` },
        { id: 'of1-tlxxx-16', number: '16', text: `E em todas as scripturas, que passarem ás partes, porão per sua letra as pagas, para se saber, se levam mais do que thes he taxado. E nas scripturas, de de que não houverem, ou não quizerem levar dinheiro, porão nihil. E fazendo o contrário disto, não pondo a paga, pola primeira vez tornem á parte todo o que levaram, e outro tanto paguem para os presos pobres: e pola segunda vez hajam a dita pena, e mais sejam suspensos dos Officios per seis mezes. E pola terceira sejam privados delles. E o Tabellião, que levar mais do que lhe he ordenado, haverá as penas conteúdas no quinto Livro, no Titulo 72: Da pena, que haverão os Officiaes, que levam mais do conteúdo em seu Regimento.` },
        { id: 'of1-tlxxx-17', number: '17', text: `E o que fizer scriptura falsa, ou auto falso, morrerá morte natural, e perderá toda sua fazenda, como se contém no Livro quinto, Titulo 52: Dos que falsificam sinal, ou sello del Rei, etc.` },
        { id: 'of1-tlxxx-18', number: '18', text: `E o que levar mais que o conteúdo em seu Regimento, perderá o Officio, e mais haverá as penas, que se contém no Livro quinto, no Titulo 72: Da pena, que haverão os Officiaes, etc.` },
        { id: 'of1-tlxxx-19', number: '19', text: `E o que servir sem carta, seja degradado dez annos para o Brasil, e por esse mesmo feito perca o Officio, e nunca o mais haja, nem outro algum de Justiça, e pague da cadea vinte cruzados, ametade para os Captivos, e a outra para quem o accusar.` },
        { id: 'of1-tlxxx-20', number: '20', text: `E nenhum Tabellião poderá vender, nem renunciar o Officio em outra pessoa sem nossa special licença, nem o renunciará, quando stiver doente, ou tiver nelle feito alguns erros, como diremos no Titulo 96: Dos que vendem, ou renunciam os Officios, sem nossa licença, e sob as penas hi conteúdas.` },
        { id: 'of1-tlxxx-21', number: '21', text: `E assi serão obrigados a se casarem, A responsabilidade criminal tem seu assento no art. 136 § 5 do respectivo Codigo.

como se contém no Titulo 94: Que não tenham Officios publicos os menores de vinte cinco annos, nem os homens solteiros.

Tahelliães pelos Senhores de terras.` },
        { id: 'of1-tlxxx-22', number: '22', text: `E qualquer Tabellião que se chamar pelo Senhor da terra, que para isso não tiver expressa doação, perderá o Officio, e nunca mais o haverá, nem outro algum Officio de Justiça, e pagará vinte cruzados, ametade para nossa Camera, e a outra para quem o accusar.` },
        { id: 'of1-tlxxx-23', number: '23', text: `E a pessoa, que aceitar o Officio de Tabellião novamente creado per qualquer Senhor de terra, haverá pena de falsario.` },
        { id: 'of1-tlxxx-24', number: '24', text: `E o que aceitar o Officio de Tabellião de algum Senhor de terras, que não tiver mais poder, que para apresentar, e o servir, sem vir tirar Carta e Regimento da Chancellaria, perderá o Officio, e haverá as mais penas, que são conteúdas no segundo Livro, no Titulo 45: Em que maneira os Senhores de terras.` },
        { id: 'of1-tlxxx-25', number: '25', text: `E o que houver Officio de Tabellião, por lho dar algum Senhor de terras, que tenha poder de lho dar, sem vir á nossa Chancellaria, se o tal Tabellião aceitar do tal Senhor de terras. Regimento de seu Officio, que não for tal, como o Chancellor Mór dá aos Tabelliães na nossa Chancellaria, perderá o Officio, e haverá a mais pena conteúda no Titulo 45: Em que maneira os Senhores de terras.` },
        { id: 'of1-tlxxx-26', number: '26', text: `E o que per sentença perder o Officio, que lhe for dado per algum Senhor de terras; e o tornar a haver de sua mão sem nossa expressa licença, perca o dito Officio, e nunca o mais possa haver, nem outro algum de Justiça. E será preso e degradado dous annos para Africa, e da cadea pague vinte cruzados, ametade para quem o accusar, e a outra para nossa Camera.` },
      ],
    },
  ],
};
